async function refreshAccount(){const sb=getSupabase();if(!sb||!authState.user)return;try{const uid=authState.user.id;await sb.rpc('ensure_account');await sb.rpc('settle_my_cycles');await Promise.all([loadPlans(),loadMoneySettings(),loadCNRewards()]);const [accountRes,ledgerRes,cycleRes,notificationRes]=await Promise.all([sb.from('accounts').select('id,currency,status').eq('user_id',uid).maybeSingle(),sb.from('ledger_entries').select('id,kind,amount_cents,reference_id,status,description,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(100),sb.from('investment_cycles').select('id,plan_name,principal_cents,started_at,ends_at,status').eq('user_id',uid).order('created_at',{ascending:false}),sb.from('notifications').select('id,title,body,type,unread,created_at').eq('user_id',uid).order('created_at',{ascending:false}).limit(50)]);if(ledgerRes.error)throw ledgerRes.error;const ledgerRows=ledgerRes.data||[],cycleRows=cycleRes.data||[];const posted=ledgerRows.filter(x=>x.status==='posted').reduce((a,x)=>a+Number(x.amount_cents),0);const invested=cycleRows.filter(x=>x.status==='active').reduce((a,x)=>a+Number(x.principal_cents),0);const accrued=ledgerRows.filter(x=>x.status==='posted'&&x.kind==='investment_return').reduce((a,x)=>a+Number(x.amount_cents),0);balances={total:((posted+invested)/100).toFixed(2),available:(posted/100).toFixed(2),invested:(invested/100).toFixed(2),accrued:(accrued/100).toFixed(2)};activeCycles=cycleRows.map(c=>({...c,planName:c.plan_name,invested:(Number(c.principal_cents)/100).toFixed(2),startedAt:new Date(c.started_at).getTime(),endsAt:new Date(c.ends_at).getTime(),settled:c.status!=='active'}));notifications=(notificationRes.data||[]).map(n=>({...n,createdAt:new Date(n.created_at).getTime()}));try{const [pinRes,mfaRes]=await Promise.all([sb.rpc('has_withdrawal_pin'),sb.auth.mfa.listFactors()]);profileSecurity={pin:Boolean(pinRes.data),mfa:(mfaRes.data?.totp||[]).some(f=>f.status==='verified')};}catch(secErr){console.warn('Security status load failed',secErr);}try{const {data:prof}=await sb.from('profiles').select('avatar_url').eq('user_id',uid).maybeSingle();if(prof?.avatar_url){const {data:signed}=await sb.storage.from('avatars').createSignedUrl(prof.avatar_url,3600);profile.avatar=signed?.signedUrl||'';}else{profile.avatar='';}}catch(avErr){console.warn('Avatar load failed',avErr);}return accountRes.data;}catch(error){console.warn('Account refresh failed',error);}}
