function currencyForCountry(country){ const value=String(country||'').toLowerCase(); return CURRENCY_PROFILES.find(profile=>profile.countries.some(name=>value.includes(name)))||CURRENCY_PROFILES.find(profile=>profile.code==='USD'); }
function localAmount(value){ const info=currencyForCountry(profile.country); return new Intl.NumberFormat(info.locale,{style:'currency',currency:info.code,currencyDisplay:'code',minimumFractionDigits:info.decimals,maximumFractionDigits:info.decimals}).format(toAmount(value)*info.rate); }
function moneyText(value){ return `${formatMoney(value)} USD · ${localAmount(value)}`; }
function currencyReference(){ const info=currencyForCountry(profile.country); return `1 USD ≈ ${new Intl.NumberFormat(info.locale,{maximumFractionDigits:info.decimals}).format(info.rate)} ${info.code}`; }

function notificationAge(timestamp){ const mins=Math.max(0,Math.floor((Date.now()-Number(timestamp))/60000)); return mins<1?'Just now':mins<60?`${mins}m ago`:mins<1440?`${Math.floor(mins/60)}h ago`:`${Math.floor(mins/1440)}d ago`; }

