async function apiCall(path,opts={}){const sb=getSupabase();const {data}=await sb.auth.getSession();const token=data?.session?.access_token;const res=await fetch(path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{})}});const j=await res.json().catch(()=>({}));if(!res.ok)throw new Error(j.error||'Request failed');return j;}
async function loadMoneySettings(){const sb=getSupabase();if(!sb)return;try{const [fx,st,rs]=await Promise.all([sb.from('fx_rates').select('currency,units_per_usd'),sb.from('app_settings').select('key,value'),sb.rpc('my_referral_stats')]);(fx.data||[]).forEach(r=>fxRates[r.currency]=Number(r.units_per_usd));(st.data||[]).forEach(r=>appSettings[r.key]=Number(r.value));referralStats=rs.data||null;}catch(e){console.warn(e);}}
function updateDepositPreview(){const c=document.querySelector('#dep-country')?.value;const cur=(MARZ_COUNTRIES.find(x=>x[0]===c)||[])[2];const amt=Number(document.querySelector('#dep-amount')?.value||0);const el=document.querySelector('#dep-preview');const lab=document.querySelector('#dep-cur');if(lab)lab.textContent=cur||'';if(el)el.textContent=cur&&fxRates[cur]&&amt>0?`≈ ${(amt/fxRates[cur]).toFixed(2)} USD will be added to your balance`:'';const ph=document.querySelector('#dep-phone-wrap');if(ph)ph.style.display=document.querySelector('#dep-method')?.value==='card'?'none':'';}
async function pollPayment(id,tries=40){for(let i=0;i<tries;i++){await new Promise(r=>setTimeout(r,5000));try{const r=await apiCall(`/api/public/payments/status?id=${id}`);if(r.status==='completed'){await refreshAccount();render();toast('Deposit received','Your balance has been updated.');return;}if(r.status==='failed'){toast('Deposit failed','The payment was not completed.');return;}}catch(e){}}}
function termLabel(d){d=Number(d);return d===21?'3 weeks':d===30?'1 month':`${d} days`;}
function mapPlanRow(r){return {id:r.id,name:r.name,asset:r.asset,assets:[r.asset],category:r.category,invest:Number(r.invest).toFixed(2),earning:Number(r.earning).toFixed(2),earningFrequency:'per day',estimatedTotal:Number(r.estimated_total).toFixed(2),term:termLabel(r.term_days),termDays:r.term_days,status:r.status,hot:r.hot,risk:r.risk,fees:'No fee',liquidity:'Locked',underlying:`${r.asset} cycle`,network:r.network,description:r.description,active:r.active,sortOrder:r.sort_order,maxInvestors:Number(r.max_investors||0),cnReward:Number(r.cn_reward||0),roiPercent:Number(r.roi_percent||0),investors:Number(planCounts[r.id]||0)};}
let planCounts={};function slotText(c){return c.maxInvestors>0?`${c.investors}/${c.maxInvestors}`:'';}function planFull(c){return c.maxInvestors>0&&c.investors>=c.maxInvestors;}
async function loadPlans(){const sb=getSupabase();if(!sb)return;try{const cr=await sb.rpc('plan_investor_counts');if(!cr.error&&cr.data){planCounts={};cr.data.forEach(x=>planCounts[x.plan_id]=Number(x.investors));}const {data,error}=await sb.from('investment_plans').select('*').eq('active',true).order('sort_order').order('created_at');if(!error&&data)earnPlans=data.map(mapPlanRow);}catch(e){console.warn('Plans load failed',e);}}
function planDurationDays(term){ return term.includes('3 weeks') ? 21 : term.includes('1 month') ? 30 : Number.parseInt(term,10)||14; }
function cycleAccruedProfit(c, now=Date.now()){ const plan=earnPlans.find(p=>p.name===c.planName); if(!plan||c.settled)return 0; const elapsedDays=Math.max(0,Math.floor((now-c.startedAt)/86400000)); const maxDays=planDurationDays(plan.term); return Math.min(toAmount(plan.estimatedTotal), elapsedDays*toAmount(plan.earning)); }
function formatRemaining(ms){ if(ms<=0) return 'Cycle ended'; const total=Math.floor(ms/1000); const days=Math.floor(total/86400); const hours=Math.floor((total%86400)/3600); const minutes=Math.floor((total%3600)/60); const seconds=total%60; return `${days}d ${String(hours).padStart(2,'0')}h ${String(minutes).padStart(2,'0')}m ${String(seconds).padStart(2,'0')}s`; }
function settleEndedCycles(){ return; const now=Date.now(); let changed=false; activeCycles=activeCycles.map(c=>{ if(c.settled || c.endsAt>now) return c; const plan=earnPlans.find(p=>p.name===c.planName); if(!plan) return {...c,settled:true}; const principal=toAmount(plan.invest); const profit=toAmount(plan.estimatedTotal); balances.available=(toAmount(balances.available)+principal+profit).toFixed(2); balances.invested=Math.max(0,toAmount(balances.invested)-principal).toFixed(2); balances.total=(toAmount(balances.total)+profit).toFixed(2); changed=true; return {...c,settled:true,settledAt:now}; }); if(changed){ saveBalances(); saveActiveCycles(); activeCycles.filter(c=>c.settled && c.settledAt===now).forEach(c=>{ const plan=earnPlans.find(p=>p.name===c.planName); if(plan)addNotification('Cycle completed',`${plan.name} settled: ${moneyText(plan.invest)} principal and ${moneyText(plan.estimatedTotal)} profit were released.`,'success'); }); } }
function activeCycleCard(c){ const plan=earnPlans.find(p=>p.name===c.planName); if(!plan) return ''; const remaining=c.endsAt-Date.now(); return `<article class="card cycle-card active-demo-card"><div class="cycle-head"><div class="cycle-title"><div class="coin ${plan.asset==='ETH'?'eth':plan.asset==='USDT'?'usdt':''}">${icon(plan.asset)}</div><div><div class="cycle-name">${plan.name}</div><div class="cycle-asset">${plan.assets.join(' · ')} · active</div></div></div><span class="badge active">Active</span></div><div class="cycle-main"><div class="cycle-return">${moneyText(plan.earning)}<small>Profit / day</small></div><div class="cycle-invested"><strong>${moneyText(plan.invest)}</strong><span>Deducted from available</span></div></div><div class="meta-grid"><div><span class="meta-label">Term</span><span class="meta-value">${plan.term}</span></div><div><span class="meta-label">Ends</span><span class="meta-value">${new Date(c.endsAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</span></div><div><span class="meta-label">Risk</span><span class="meta-value">${plan.risk}</span></div></div><div class="linked-plan"><div><span class="linked-plan-label">Profit & return status</span><strong>Locked until cycle ends</strong></div><div class="linked-plan-values"><span>Estimated total ${moneyText(plan.estimatedTotal)}</span><span class="countdown" data-ends="${c.endsAt}">${formatRemaining(remaining)}</span></div><div class="helper">Principal and all profits remain locked until the investment cycle ends.</div></div></article>`; }
async function addDemoCycle(planName){ const plan=earnPlans.find(p=>p.name===planName); if(!plan) return; if(planFull(plan)){toast('Plan full',`${plan.name} has reached ${slotText(plan)} investors.`);return;} if(toAmount(balances.available)<toAmount(plan.invest)){ showModal('Insufficient balance',`<p>${plan.name} requires <strong>${plan.invest} USDT</strong>, but your available balance is only <strong>${balances.available} USDT</strong>.</p>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="deposit">Add deposit</button>`); return; } const {error}=await getSupabase().rpc('start_investment',{p_plan_id:plan.id}); if(error){toast('Could not start',error.message);return;} modalRoot.innerHTML=''; await refreshAccount(); navigateView('home'); toast('Investment started',`${moneyText(plan.invest)} deducted. Profits remain locked until cycle end.`); }
function addDemoCycleOld(planName){ settleEndedCycles(); const plan=earnPlans.find(p=>p.name===planName); if(!plan) return; const principal=toAmount(plan.invest); const available=toAmount(balances.available); const existing=activeCycles.find(c=>c.planName===plan.name && !c.settled && c.endsAt>Date.now()); if(existing){ modalRoot.innerHTML=''; navigateView('home'); toast('Already active','This plan is already in your active cycles.'); return; } if(available<principal){ showModal('Insufficient balance',`<p>${plan.name} requires <strong>${plan.invest} USDT</strong>, but your available balance is only <strong>${balances.available} USDT</strong>.</p>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="deposit">Add deposit</button>`); return; } const now=Date.now(); const endsAt=now+planDurationDays(plan.term)*86400000; balances.available=(available-principal).toFixed(2); balances.invested=(toAmount(balances.invested)+principal).toFixed(2); saveBalances(); activeCycles=[{id:`${plan.name}-${now}`,planName:plan.name,invested:plan.invest,startedAt:now,endsAt,funded:true,settled:false}, ...activeCycles]; saveActiveCycles(); modalRoot.innerHTML=''; navigateView('home'); addNotification('Investment started',`${plan.name} started with ${moneyText(plan.invest)} deducted from available balance.`,'success'); toast('Investment started',`${moneyText(plan.invest)} deducted. Profits remain locked until cycle end.`); }
async function addDemoDeposit(){ const method=document.querySelector('#dep-method').value, country=document.querySelector('#dep-country').value, amount=Number(document.querySelector('#dep-amount').value), phone=String(document.querySelector('#dep-phone')?.value||'').replace(/[\s-]/g,''); if(!(amount>0)){toast('Enter a valid amount','Enter how much you want to deposit.');return;} if(method==='mobile_money'&&!/^\+?[0-9]{8,15}$/.test(phone)){toast('Check your number','Enter your mobile money number with country code.');return;} const btn=document.querySelector('[data-action="demo-deposit"]'); if(btn){btn.disabled=true;btn.textContent='Processing…';} try{ const r=await apiCall('/api/public/payments/deposit',{method:'POST',body:JSON.stringify({method,country,amount,phone:method==='mobile_money'?phone:undefined})}); if(r.redirect_url){ window.open(r.redirect_url,'_blank'); showModal('Complete card payment','<p>Finish the payment in the card window that just opened. Your balance updates automatically once it is confirmed.</p>'); } else { showModal('Confirm on your phone',`<p>A payment prompt for <strong>${Number(r.local_amount).toLocaleString()} ${r.currency}</strong> was sent to <strong>${escapeHTML(phone)}</strong>. Enter your PIN to approve it.</p><div class="helper">Your balance updates automatically once the payment is confirmed.</div>`); } pollPayment(r.id); }catch(e){ toast('Deposit failed',e.message); if(btn){btn.disabled=false;btn.textContent='Pay now';} } }
function addDemoDepositOld(){ const input=document.querySelector('#demo-deposit-amount'); const amount=Number(input?.value); if(!Number.isFinite(amount)||amount<=0){ toast('Enter a valid amount','Use a deposit greater than 0 USDT.'); return; } const value=amount.toFixed(2); balances.available=(toAmount(balances.available)+amount).toFixed(2); balances.total=(toAmount(balances.total)+amount).toFixed(2); saveBalances(); addNotification('Deposit added',`${moneyText(value)} was added to your available balance.`,'success'); modalRoot.innerHTML=''; render(); toast('Deposit added',`${moneyText(value)} added to available balance. No real transaction was created.`); }
function resetDemoBalances(){ balances={total:'0.00',available:'0.00',invested:'0.00',accrued:'0.00'}; activeCycles=[]; saveBalances(); saveActiveCycles(); modalRoot.innerHTML=''; render(); toast('Data cleared','Balances, active cycles, and income records are now zero.'); }
function updateCountdowns(){ document.querySelectorAll('[data-ends]').forEach(el=>{ el.textContent=formatRemaining(Number(el.dataset.ends)-Date.now()); }); }
function icon(name){ const symbol=name.toLowerCase(); return `<img class="crypto-logo" src="/public/crypto/${symbol}.svg" alt="${name} logo" loading="lazy">`; }
function notificationPanel(){ const unread=notifications.filter(n=>n.unread).length; return `<div class="notification-panel" role="dialog" aria-label="Notifications"><div class="notification-panel-head"><strong>Notifications</strong><button class="notification-mark" data-action="mark-all-read" ${unread?'':'disabled'}>Mark all read</button></div><div class="notification-list">${notifications.length?notifications.map(n=>`<button class="notification-item ${n.unread?'unread':''}" data-action="read-notification" data-notification-id="${escapeHTML(n.id)}"><span class="notification-dot ${n.type}"></span><span class="notification-copy"><strong>${escapeHTML(n.title)}</strong><span>${escapeHTML(n.body)}</span><small>${notificationAge(n.createdAt)}</small></span></button>`).join(''):'<div class="notification-empty">You are all caught up.</div>'}</div></div>`; }
function shell(title, eyebrow, subtitle, body){ const unread=notifications.filter(n=>n.unread).length; const initials=escapeHTML(profile.name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'A'); return `<div class="page"><header class="topbar"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="header-actions"><div class="notification-wrap"><button class="icon-btn notification-bell ${unread?'has-unread':''}" data-action="notifications" aria-label="Notifications" aria-expanded="${notificationOpen}">🔔${unread?`<span class="notification-count">${unread>9?'9+':unread}</span>`:''}</button>${notificationOpen?notificationPanel():''}</div><button class="icon-btn" data-action="support" aria-label="Support center">💬</button><button class="avatar" data-nav="profile" aria-label="Open your profile" title="Your profile">${profile.avatar?`<img class="avatar-img" src="${escapeHTML(profile.avatar)}" alt="">`:initials}</button></div></header>${body}</div>`; }
function risk(){ return ``; }
function stat(label, value, helper='', primary=false){ const amount=toAmount(value); return `<article class="stat-card ${primary?'primary':''}"><div class="stat-label">${label}${helper ? '<span class="info-dot">i</span>' : ''}</div><div class="stat-value"><strong>${formatMoney(amount)} <span class="unit">USD</span></strong><small class="local-stat">${localAmount(amount)}</small></div>${helper ? `<div class="helper">${helper}</div>` : ''}</article>`; }
function cycleCard(c, detail=false){ const linked= c.planName ? earnPlans.find(p=>p.name===c.planName) : null; return `<article class="card cycle-card"><div class="cycle-head"><div class="cycle-title"><div class="coin ${c.asset==='ETH'?'eth':c.asset==='USDT'?'usdt':''}">${icon(c.asset)}</div><div><div class="cycle-name">${c.name}</div><div class="cycle-asset">${c.asset} </div></div></div><span class="badge ${c.status.toLowerCase()==='open'?'open':'active'}">${c.status}</span></div><div class="cycle-main"><div class="cycle-return">${c.performance}<small>${c.performanceType}</small></div><div class="cycle-invested"><strong>${c.invested === '—' ? 'Not invested' : c.invested + ' USDT'}</strong><span>${c.invested === '—' ? 'Available plan' : 'Invested amount'}</span></div></div><div class="meta-grid"><div><span class="meta-label">Term</span><span class="meta-value">${c.term}</span></div><div><span class="meta-label">Next update</span><span class="meta-value">${c.next}</span></div><div><span class="meta-label">Risk</span><span class="meta-value">${c.risk}</span></div></div>${linked?`<div class="linked-plan"><div><span class="linked-plan-label">Linked investment plan</span><strong>${linked.name}</strong></div><div class="linked-plan-values"><span>${moneyText(linked.earning)} / day</span><span>Estimated after cycle ${moneyText(linked.estimatedTotal)}</span></div><button class="btn small" data-cycle="${linked.name}">Open linked plan</button></div>`:''}${detail ? `<div style="margin-top:15px"><button class="btn small primary" data-cycle="${c.name}">View details</button></div>` : ''}</article>`; }
function renderHome(){ const openCycles=activeCycles.filter(c=>!c.settled); const hotPlans=earnPlans.filter(p=>p.hot||p.name==='Ethereum Elite').slice(0,2); return shell(`Good morning, ${escapeHTML(profile.name.split(/\s+/)[0]||'there')}`,'Home','Your CRYPTONVA wallet and active investment plans.',`${risk()}<section class="wallet-card"><div class="wallet-card-top"><div class="wallet-brand"><img src="/public/cryptonva-symbol.png" alt="" class="wallet-brand-symbol"><span><b>CRYPTO</b><strong>NOVA</strong></span></div><button class="wallet-more" data-action="wallet-info" aria-label="Wallet details">•••</button></div><div class="wallet-local-row"><span>Local currency balance</span><strong>${localAmount(balances.available)}</strong><span class="network-pill">${currencyForCountry(profile.country).code}</span></div><div class="wallet-balance"><span>Available balance</span><div class="wallet-balance-pair"><strong>${formatMoney(balances.available)} <small>USD</small></strong><b>${localAmount(balances.available)}</b></div><em>${currencyReference()}</em><div class="wallet-total"><span>Total account value</span><strong>${formatMoney(balances.total)} <small>USD</small></strong><b>${localAmount(balances.total)}</b></div></div>${cnHomeRow()}<div class="wallet-actions"><button class="wallet-action deposit" data-action="deposit"><span>↓</span><strong>Deposit</strong></button><button class="wallet-action withdraw" data-action="withdraw"><span>↑</span><strong>Withdraw</strong></button><button class="wallet-action invite" data-action="invite"><span>♧</span><strong>Invite</strong></button></div></section><section class="home-section"><div class="home-section-heading"><div><h2>Hot investment plans</h2><p>Quick access to two featured Earn plans</p></div><button class="text-link" data-nav="earn">See all <span>→</span></button></div><div class="hot-quick-grid">${hotPlans.map((plan,index)=>`<button class="hot-quick-card ${index===1?'gold-accent':''}" data-cycle="${plan.name}"><div class="hot-quick-top"><div class="coin ${plan.asset==='ETH'?'eth':plan.asset==='USDT'?'usdt':''}">${icon(plan.asset)}</div><span class="hot-chip">🔥 HOT</span></div><strong>${plan.name}</strong><span class="hot-quick-meta">${moneyText(plan.invest)} · ${plan.term}</span><div class="hot-quick-return"><b>${moneyText(plan.earning)}</b><span>/ day</span></div><small>Estimated ${moneyText(plan.estimatedTotal)} after cycle</small></button>`).join('')}</div></section><section class="home-section"><div class="home-section-heading"><div><h2>Active investment plans</h2><p>Your funded cycles and locked returns</p></div><span class="network-label">${openCycles.length} active</span></div><div class="cycle-grid">${openCycles.length?openCycles.map(c=>activeCycleCard(c)).join(''):`<div class="card empty-state active-empty"><strong>No active plans yet.</strong><br><span>Make a deposit, then open Earn to start a cycle.</span><br><button class="btn small primary" data-nav="earn" style="margin-top:12px">Explore Earn</button></div>`}</div></section>`); }
function renderEarn(){ const visible=earnPlans.filter(c=>activeFilter==='All'||c.category.includes(activeFilter)||c.assets.includes(activeFilter)); return shell('Explore products','Earn marketplace',`Plans display USD and ${currencyForCountry(profile.country).code} for your registered country.`,`${risk()}<div class="filter-row">${['All','BTC','ETH','LTC','USDT','Short term','Long term'].map(f=>`<button class="filter ${activeFilter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div class="market-list">${visible.map(c=>`<article class="card market-card${c.hot?' hot-plan':''}"><div class="market-title"><div class="cycle-title"><div class="coin ${c.asset==='ETH'?'eth':c.asset==='USDT'?'usdt':''}">${icon(c.asset)}</div><div>${c.name}${c.hot?'<span class="badge high hot-label" style="margin-left:7px">🔥 HOT</span>':''}<small>${c.assets.join(' · ')} · ${c.status}</small></div></div>${c.maxInvestors>0?`<span class="badge ${planFull(c)?'high':''}" style="margin-left:auto;white-space:nowrap">${slotText(c)}${planFull(c)?' · Full':''}</span>`:''}</div><div class="market-detail"><span>Investment</span><strong>${moneyText(c.invest)}</strong></div><div class="market-detail"><span>Earning / day</span><strong>${moneyText(c.earning)}</strong></div><div class="market-detail"><span>Estimated after cycle</span><strong>${moneyText(c.estimatedTotal)}</strong></div><div class="market-detail"><span>Term</span><strong>${c.term}</strong></div><div class="market-detail"><span>Risk / fee</span><strong>${c.risk} · ${c.fees}</strong></div>${cnPlanBadge(c)}<button class="btn small" data-cycle="${c.name}">View details</button></article>`).join('')}</div>`); }
function renderIncome(){ const openCycles=activeCycles.filter(c=>!c.settled); const projectedProfit=openCycles.reduce((sum,c)=>{const plan=earnPlans.find(p=>p.name===c.planName);return sum+(plan?toAmount(plan.estimatedTotal):0);},0); const accruedProfit=openCycles.reduce((sum,c)=>sum+cycleAccruedProfit(c),0); const realizedProfit=activeCycles.filter(c=>c.settled).reduce((sum,c)=>{const plan=earnPlans.find(p=>p.name===c.planName);return sum+(plan?toAmount(plan.estimatedTotal):0);},0); const summary=[['Available',balances.available,'Withdrawable balance'],['Pending','0.00','Awaiting settlement'],['Accrued',accruedProfit.toFixed(2),'Earned and locked'],['Projected',projectedProfit.toFixed(2),'Full-cycle estimate'],['Realized',realizedProfit.toFixed(2),'Completed cycle profit'],['Unrealized',accruedProfit.toFixed(2),'Earned and locked']]; const rows=activeCycles.map(c=>{const plan=earnPlans.find(p=>p.name===c.planName);if(!plan)return '';const settled=c.settled;const amount=settled?toAmount(plan.estimatedTotal):cycleAccruedProfit(c);return `<tr><td>${new Date(settled?c.settledAt:c.startedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}</td><td>${plan.name}</td><td>${settled?'Cycle profit realized':'Return earned to date'}</td><td><strong>${moneyText(amount)}</strong></td><td><span class="status-text ${settled?'realized':'accrued'}">${settled?'Realized':'Locked'}</span></td></tr>`;}).join(''); const history=rows?`<div class="table-wrap"><table class="income-table"><thead><tr><th>Date</th><th>Cycle</th><th>Type</th><th>Amount</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty-state"><strong>No income records yet.</strong><br><span>Profits and returns appear once a funded cycle is started.</span></div>'; return shell('Income','Performance ledger',`USD and ${currencyForCountry(profile.country).code} earnings for your registered country.`,`<div class="summary-grid">${summary.map(s=>stat(s[0],s[1],s[2])).join('')}</div><p class="helper" style="margin-top:12px">Return earned to date increases once each investment day completes. It remains locked until the related cycle ends; Projected is the full-cycle estimate. Reference rate: ${currencyReference()}.</p><section class="section"><div class="section-heading"><div><h2>Income history</h2><p>Records · USD + ${currencyForCountry(profile.country).code}</p></div></div><div class="card table-card">${history}</div></section><section class="section"><div class="section-heading"><div><h2>Reports</h2><p>Download your statements and history.</p></div></div><div class="report-grid">${['Monthly statement','Cycle statement','Transaction history','Download report'].map(x=>`<button class="btn" data-action="coming-soon">${x}</button>`).join('')}</div></section>`); }

async function refreshAdmin(){
  const sb=getSupabase(); if(!sb||!authState.user) return false;
  try {
    const role=await sb.from('admin_roles').select('role').eq('user_id',authState.user.id).maybeSingle();
    isAdmin=Boolean(role.data?.role);
    if(!isAdmin) return false;
    const [ov,users,withdrawals,kyc,audit,support,plansRes]=await Promise.all([
      sb.rpc('admin_overview'), sb.rpc('admin_list_users'), sb.rpc('admin_list_withdrawals'),
      sb.rpc('admin_list_kyc'), sb.rpc('admin_list_audit'), sb.rpc('admin_list_support'), sb.from('investment_plans').select('*').order('sort_order').order('created_at')
    ]);
    if(ov.error) throw ov.error;
    adminCache={plans:(plansRes?.data||[]).map(mapPlanRow),overview:ov.data||{},users:users.data||[],withdrawals:withdrawals.data||[],kyc:kyc.data||[],audit:audit.data||[],support:support.data||[]};
    await loadAdminCN();
    return true;
  } catch(error){ console.warn('Admin refresh failed',error); isAdmin=false; return false; }
}
function adminMoney(cents){return (Number(cents||0)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' USD';}
function adminNav(){ if(!isAdmin) return ''; return `<button class="nav-item ${currentView==='admin'?'active':''}" data-nav="admin"><span class="nav-icon">▣</span><span>Admin Console</span></button>`; }
function adminKpi(label,value,sub){return `<div class="admin-kpi card"><span>${escapeHTML(label)}</span><strong>${escapeHTML(value)}</strong><small>${escapeHTML(sub||'')}</small></div>`;}
function renderAdmin(){
 const o=adminCache.overview||{};
 const tabs=[['overview','Overview'],['users','Users'],['withdrawals','Withdrawals'],['kyc','KYC Review'],['restrictions','Risk & Restrictions'],['payouts','Payout Queue'],['plans','Plans & Cycles'],['settings','Payments & Referrals'],['support','Support'],['cn','CN Tasks & Campaigns'],['audit','Audit Log']];
 let body='';
 if(adminSection==='overview') body=`<div class="admin-grid">${adminKpi('Total users',o.users??0,'Registered accounts')}${adminKpi('Total deposits',adminMoney(o.total_deposits_cents),'Posted ledger deposits')}${adminKpi('Total paid out',adminMoney(o.total_withdrawals_cents),'Posted withdrawals')}${adminKpi('Pending to pay',adminMoney(o.pending_withdrawals_cents),'Approved by operations only after review')}${adminKpi('Withdrawal requests',o.pending_withdrawals??0,'Awaiting decision')}${adminKpi('Pending KYC',o.pending_kyc??0,'Awaiting compliance review')}${adminKpi('Restricted users',o.restricted_users??0,'Restricted or suspended')}</div><section class="admin-panel card"><h2>Operations controls</h2><p>Use the queues below for financial operations. Every administrative decision is recorded in the audit log.</p><div class="admin-actions"><button class="btn primary" data-admin-section="withdrawals">Review withdrawals</button><button class="btn" data-admin-section="kyc">Review KYC</button><button class="btn" data-admin-section="users">Manage users</button><button class="btn" data-admin-section="audit">View audit log</button></div></section>`;
 else if(adminSection==='users') body=`<div class="admin-panel card"><div class="admin-heading"><div><h2>Users list</h2><p>Search and manage account restrictions.</p></div><button class="btn" data-action="admin-refresh">Refresh</button></div><input class="input" type="search" data-admin-user-search placeholder="Search by email, KYC or status" value="${escapeHTML(adminUserQuery)}" style="width:100%;margin:8px 0 12px"><div class="table-wrap"><table class="admin-table"><thead><tr><th>Email</th><th>KYC</th><th>Account status</th><th>Created</th><th>Action</th></tr></thead><tbody>${adminCache.users.map(u=>`<tr data-user-row="${escapeHTML(((u.email||'')+' '+u.kyc_status+' '+u.restriction_status).toLowerCase())}" ${adminUserQuery&&!((u.email||'')+' '+u.kyc_status+' '+u.restriction_status).toLowerCase().includes(adminUserQuery.toLowerCase())?'style="display:none"':''}><td>${escapeHTML(u.email||'')}</td><td>${escapeHTML(u.kyc_status)}</td><td><span class="status-text ${u.restriction_status==='active'?'realized':'accrued'}">${escapeHTML(u.restriction_status)}</span></td><td>${new Date(u.created_at).toLocaleDateString()}</td><td><button class="btn small" data-admin-user="${u.user_id}" data-admin-status="${u.restriction_status==='active'?'suspended':'active'}">${u.restriction_status==='active'?'Suspend':'Enable'}</button></td></tr>`).join('')}</tbody></table></div></div>`;
 else if(adminSection==='withdrawals'||adminSection==='payouts') { const rows=adminCache.withdrawals.filter(w=>adminSection==='withdrawals'?w.status==='pending':['approved','processing','paid','failed'].includes(w.status)); body=`<div class="admin-panel card"><div class="admin-heading"><div><h2>${adminSection==='withdrawals'?'Withdrawal requests':'Payout queue'}</h2><p>${rows.length} request(s) shown.</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Amount</th><th>Destination</th><th>Status</th><th>Requested</th><th>Action</th></tr></thead><tbody>${rows.map(w=>`<tr><td>${escapeHTML(w.email)}</td><td><strong>${adminMoney(w.amount_cents)}</strong></td><td>${escapeHTML(w.destination)}</td><td>${escapeHTML(w.status)}</td><td>${new Date(w.requested_at).toLocaleString()}</td><td>${w.status==='pending'?`<button class="btn small primary" data-withdraw-approve="${w.id}">Approve</button><button class="btn small" data-withdraw-reject="${w.id}">Reject</button>`:w.status==='approved'?`<button class="btn small primary" data-withdraw-approve="${w.id}">Send payout</button>`:escapeHTML(w.status)}</td></tr>`).join('')||`<tr><td colspan="6">No requests in this queue.</td></tr>`}</tbody></table></div></div>`; }
 else if(adminSection==='kyc') body=`<div class="admin-panel card"><div class="admin-heading"><div><h2>KYC approval & rejection</h2><p>Compliance decisions are recorded with reviewer and timestamp.</p></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Document</th><th>Status</th><th>Submitted</th><th>Action</th></tr></thead><tbody>${adminCache.kyc.map(k=>`<tr><td>${escapeHTML(k.email)}</td><td>${escapeHTML(k.document_type||'—')}</td><td>${escapeHTML(k.status)}</td><td>${new Date(k.created_at).toLocaleString()}</td><td>${k.status==='pending'?`<button class="btn small primary" data-kyc-approve="${k.id}">Approve</button><button class="btn small" data-kyc-reject="${k.id}">Reject</button>`:'—'}</td></tr>`).join('')||`<tr><td colspan="5">No KYC submissions.</td></tr>`}</tbody></table></div></div>`;
 else if(adminSection==='restrictions') body=`<div class="admin-panel card"><h2>Risk & restrictions</h2><p>Restrict, suspend or close accounts that trigger fraud/compliance controls. Restrictions immediately affect the account status.</p><div class="admin-grid compact">${adminCache.users.filter(u=>u.restriction_status!=='active').map(u=>adminKpi(u.email,u.restriction_status,'Restricted account')).join('')||'<div class="empty-state">No restricted users.</div>'}</div></div>`;
 else if(adminSection==='settings') body=`<div class="admin-panel card"><h2>Payments & referrals</h2><p>Referral bonus is paid once, when an invited friend makes their first deposit.</p><div class="admin-actions"><button class="btn" data-admin-setting="referral_bonus_cents">Referral bonus: ${((appSettings.referral_bonus_cents||0)/100).toFixed(2)} USD</button><button class="btn" data-admin-setting="min_withdrawal_cents">Minimum withdrawal: ${((appSettings.min_withdrawal_cents||0)/100).toFixed(2)} USD</button></div><h2 style="margin-top:18px">Exchange rates</h2><p>How much local currency equals 1 USD. Used to convert deposits and withdrawals.</p><div class="table-wrap"><table class="admin-table"><thead><tr><th>Currency</th><th>Per 1 USD</th><th>Action</th></tr></thead><tbody>${Object.entries(fxRates).map(([c,v])=>`<tr><td>${c}</td><td>${v}</td><td>${c==='USD'?'':`<button class="btn small" data-admin-fx="${c}">Edit</button>`}</td></tr>`).join('')}</tbody></table></div></div>`;
 else if(adminSection==='plans') body=`<div class="admin-panel card"><div class="admin-heading"><div><h2>Investment plans & cycles</h2><p>Add new plans or edit existing ones. Changes appear on the Earn page for all users.</p></div><button class="btn primary" data-plan-edit="new">Add plan</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Position</th><th>Name</th><th>Investors</th><th>Asset</th><th>Invest</th><th>ROI / day</th><th>Profit / day</th><th>Total</th><th>Term</th><th>CN reward</th><th>Status</th><th>Action</th></tr></thead><tbody>${adminCache.plans.map((p,i)=>`<tr><td style="white-space:nowrap"><button class="btn small" data-plan-move="${p.id}" data-pos="${i}" ${i===0?'disabled':''}>↑</button> <input class="input" type="number" min="1" max="${adminCache.plans.length}" value="${i+1}" data-plan-pos="${p.id}" style="width:58px;display:inline-block;padding:6px"> <button class="btn small" data-plan-move="${p.id}" data-pos="${i+2}" ${i===adminCache.plans.length-1?'disabled':''}>↓</button></td><td>${escapeHTML(p.name)}</td><td>${p.maxInvestors>0?`${p.investors}/${p.maxInvestors}`:`${p.investors} / ∞`}</td><td>${escapeHTML(p.asset)}</td><td>${p.invest}</td><td>${p.roiPercent}%</td><td>${p.earning}</td><td>${p.estimatedTotal}</td><td>${escapeHTML(p.term)}</td><td>${p.cnReward>0?Number(p.cnReward).toLocaleString()+' CN':'—'}</td><td><span class="status-text ${p.active?'realized':'accrued'}">${p.active?escapeHTML(p.status):'Hidden'}</span></td><td><button class="btn small" data-plan-edit="${p.id}">Edit</button></td></tr>`).join('')}</tbody></table></div></div>`;
 else if(adminSection==='support') body=`<div class="admin-panel card"><h2>Support queue</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>Subject</th><th>Message</th><th>Status</th></tr></thead><tbody>${adminCache.support.map(x=>`<tr><td>${escapeHTML(x.email)}</td><td>${escapeHTML(x.subject)}</td><td>${escapeHTML(x.message)}</td><td>${escapeHTML(x.status)}</td></tr>`).join('')||'<tr><td colspan="4">No support tickets.</td></tr>'}</tbody></table></div></div>`;
 else if(adminSection==='cn') body=renderAdminCN();
 else body=`<div class="admin-panel card"><h2>Audit log</h2><p>Administrative actions and references.</p><div class="table-wrap"><table class="admin-table"><thead><tr><th>Time</th><th>Action</th><th>User</th><th>Reference</th></tr></thead><tbody>${adminCache.audit.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString()}</td><td>${escapeHTML(x.action)}</td><td>${escapeHTML(x.target_user_id||'—')}</td><td>${escapeHTML(x.target_reference||'—')}</td></tr>`).join('')||'<tr><td colspan="4">No audit records.</td></tr>'}</tbody></table></div></div>`;
 return shell('Admin Console','Operations','Secure administration for users, compliance, withdrawals and financial oversight.',`<div class="admin-shell ${adminNavCollapsed?'collapsed':''}"><aside class="admin-side card"><button class="admin-side-toggle" data-admin-nav-toggle aria-expanded="${!adminNavCollapsed}" title="${adminNavCollapsed?'Expand navigation':'Collapse navigation'}"><span class="admin-side-burger">☰</span><span class="admin-side-label">Navigation</span></button><nav class="admin-side-nav">${tabs.map(t=>`<button class="admin-side-item ${adminSection===t[0]?'active':''}" data-admin-section="${t[0]}" title="${t[1]}"><span>${t[1]}</span></button>`).join('')}</nav></aside><div class="admin-body">${body}</div></div>`);
}

function renderProfile(){ const name=escapeHTML(profile.name), email=escapeHTML(profile.email), phone=escapeHTML(profile.phone), country=escapeHTML(profile.country), timezone=escapeHTML(profile.timezone); const initials=escapeHTML(profile.name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'A'); return shell('Profile','Account center','Keep your personal details current.',`<div class="profile-hero card"><button class="profile-avatar avatar-btn" data-action="change-photo" title="Change profile photo">${profile.avatar?`<img class="avatar-img" src="${escapeHTML(profile.avatar)}" alt="">`:initials}<span class="avatar-edit-mark">✎</span></button><input type="file" id="avatar-file" accept="image/*" hidden><div><div class="eyebrow">CRYPTONVA account</div><h2>${name}</h2><p>${email}</p></div><span class="badge medium">Authenticated</span></div><div class="profile-grid"><section class="card profile-card profile-editor"><div class="profile-card-heading"><div><h3>Personal information</h3><p>Edit the details saved in this browser.</p></div><span class="edit-mark">✎</span></div><form data-profile-form class="profile-form"><label>Full name<input name="name" value="${name}" autocomplete="name" required></label><label>Email address<input name="email" type="email" value="${email}" autocomplete="email" required></label><label>Phone number<input name="phone" value="${phone}" autocomplete="tel"></label><label>Country<input name="country" value="${country}" autocomplete="country-name"></label><label>Time zone<input name="timezone" value="${timezone}" autocomplete="off"></label><div class="profile-save-row"><span class="helper">Saved locally on this device.</span><button class="btn primary" type="submit">Save changes</button></div></form></section><section class="card profile-card"><h3>Account status</h3><div class="detail-row"><span>Account type</span><strong>CRYPTONVA user</strong></div><div class="detail-row"><span>Verification</span><strong style="color:var(--amber)">Not connected</strong></div><div class="detail-row"><span>Data storage</span><strong>Secure account</strong></div><p class="helper">Username/password account access is active.</p><button class="btn" data-action="logout">Log out of CRYPTONVA</button></section><section class="card profile-card"><h3>Security</h3><div class="placeholder-list"><button class="placeholder profile-item" data-action="change-password"><strong>Change password</strong><span>Update ›</span></button><button class="placeholder profile-item" data-action="mfa"><strong>Enable MFA</strong><span>${profileSecurity.mfa?'On · Manage ›':'Off · Set up ›'}</span></button><button class="placeholder profile-item" data-action="withdrawal-pin"><strong>Withdrawal PIN</strong><span>${profileSecurity.pin?'Set · Change ›':'Not set · Create ›'}</span></button><button class="placeholder profile-item" data-action="login-history"><strong>Login history</strong><span>View ›</span></button><button class="placeholder profile-item" data-action="devices"><strong>Active devices</strong><span>View ›</span></button></div></section><section class="card profile-card"><h3>Documents</h3><div class="placeholder-list">${[['terms','Terms and conditions'],['privacy','Privacy policy'],['risk','Investment risk disclosure'],['agreement','Investor agreement'],['cycles','Cycle documents'],['complaints','Complaints procedure']].map(([k,x])=>`<button class="placeholder profile-item" data-action="doc" data-doc="${k}"><strong>${x}</strong><span>View ›</span></button>`).join('')}</div></section><section class="card profile-card"><h3>Support & complaints</h3><div class="placeholder-list">${[['help-center','Help center'],['contact-support','Contact support'],['secure-messages','Secure messages'],['complaint','Submit a complaint'],['report','Report suspicious activity']].map(([k,x])=>`<button class="placeholder profile-item" data-action="${k}"><strong>${x}</strong><span>Open ›</span></button>`).join('')}</div></section></div>`); }
function renderAuthLoading(){ return `<div class="auth-page auth-loading"><div class="auth-loading-card"><img src="/public/cryptonva-symbol.png" alt="CRYPTONVA" class="auth-symbol"><span class="eyebrow">CRYPTONVA</span><strong>Checking your account…</strong></div></div>`; }
function renderAuth(){ const signup=authMode==='signup'; const error=authState.error?`<div class="auth-error" role="alert">${escapeHTML(authState.error)}</div>`:''; return `<div class="auth-page"><section class="auth-visual"><div class="auth-visual-inner"><img src="/public/cryptonva-logo.png" alt="CRYPTONVA — Invest in the digital future" class="auth-logo"><div class="auth-visual-copy"><span class="eyebrow">The digital future is closer</span><h2>Build your next chapter in crypto.</h2><p>Explore transparent cycle mechanics, track your returns, and keep your digital future in view.</p><div class="auth-feature-list"><div><span>✦</span><strong>Clear by design</strong><small>Understand every plan, term, and lock-up rule.</small></div><div><span>◈</span><strong>Built for confidence</strong><small>Keep balances, activity, and profile data in one place.</small></div><div><span>↗</span><strong>Forward-looking</strong><small>Built for the next generation of digital investing.</small></div></div></div><div class="auth-legal">CRYPTONVA · INVEST IN THE DIGITAL FUTURE</div></div></section><section class="auth-panel"><div class="auth-card"><div class="auth-mini-brand"><img src="/public/cryptonva-symbol.png" alt=""><span>CRYPTON<span>VA</span></span></div><div class="auth-heading"><span class="eyebrow">${signup?'Create your account':'Secure account access'}</span><h1>${signup?'Create your CRYPTONVA account':'Welcome back'}</h1><p>${signup?'Complete your details to start your investor workspace.':'Log in with your CRYPTONVA email and password.'}</p></div><div class="auth-tabs" role="tablist"><button class="auth-tab ${!signup?'active':''}" data-auth-mode="login" role="tab" aria-selected="${!signup}">Log in</button><button class="auth-tab ${signup?'active':''}" data-auth-mode="signup" role="tab" aria-selected="${signup}">Sign up</button></div>${error}<form class="auth-form" data-auth-form novalidate>${signup?`<label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" required></label><label>Username<input name="username" autocomplete="username" placeholder="Choose a username" minlength="3" required></label><label>Telecom / phone<input name="telecom" type="tel" autocomplete="tel" placeholder="+1 555 014 0224" required></label><label>Country<input name="country" autocomplete="country-name" placeholder="Your country" required></label><label>Password<input name="password" type="password" autocomplete="new-password" placeholder="At least 8 characters" minlength="8" required></label><label>Confirm password<input name="confirmPassword" type="password" autocomplete="new-password" placeholder="Repeat your password" minlength="8" required></label><label>Invitation code (optional)<input name="inviteCode" autocomplete="off" placeholder="Enter invitation code" maxlength="16" value="${escapeHTML((()=>{try{return localStorage.getItem('cryptonva_ref')||''}catch(e){return ''}})())}" style="text-transform:uppercase"></label><label class="terms-check"><input name="terms" type="checkbox" required><span>I accept the <a href="#" data-action="terms">Terms and Conditions</a> and acknowledge the investment risk disclosure.</span></label><button class="btn primary auth-submit" type="submit">Create CRYPTONVA account <span>→</span></button>`:`<label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" required></label><label>Password<input name="password" type="password" autocomplete="current-password" placeholder="Your password" required></label><button class="btn primary auth-submit" type="submit">Log in to CRYPTONVA <span>→</span></button>`}</form><div class="auth-divider"><span>${signup?'Account creation':'Email & password'}</span></div><p class="auth-note">Your password is handled by the authentication provider. Account details personalize your investor workspace.</p><div class="auth-assurance"><span>●</span><div><strong>Protected account access</strong><small>Managed authentication · secure sessions · account fields saved for your profile</small></div></div></div></section></div>`; }
function showModal(title, body, actions='<button class="btn" data-action="close-modal">Close</button>'){ modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close">×</button></div>${body}<div class="modal-actions">${actions}</div></section></div>`; }
const DOC_TEXTS={
terms:{t:'Terms and conditions',b:'<p>By creating a CRYPTONVA account you confirm you are of legal age in your country, that the funds you invest are your own, and that you understand digital asset investments carry risk.</p><p>Accounts are personal and may not be shared or sold. We may suspend accounts involved in fraud, money laundering, or abuse of the rewards program.</p><p>Investment cycles run for their stated term; early withdrawal from an active cycle is not possible. Returns are credited to your wallet when a cycle settles.</p>'},
privacy:{t:'Privacy policy',b:'<p>We store only the data needed to run your account: your name, email, phone, country, and your investment and transaction history.</p><p>Your data is never sold. It is shared only with the payment providers that process your deposits and withdrawals, and only for that purpose.</p><p>You may request a copy or deletion of your data at any time through Contact support.</p>'},
risk:{t:'Investment risk disclosure',b:'<p>Digital asset investments are high risk. The value of assets can rise or fall sharply, and past performance does not guarantee future results.</p><p>Only invest money you can afford to lose. CRYPTONVA does not provide financial advice; plan descriptions are informational.</p><p>CN reward coins have no cash value until the token generation event (TGE) and exchange listing are completed, which are not guaranteed.</p>'},
agreement:{t:'Investor agreement',b:'<p>When you start an investment cycle you agree to the plan terms shown at that moment: the amount, the term, the earning schedule, and the withdrawal rules.</p><p>Your principal is locked for the full term. Earnings are calculated per cycle and credited on settlement.</p><p>CRYPTONVA may update plan terms for future cycles; changes never apply retroactively to active cycles.</p>'},
cycles:{t:'Cycle documents',b:'<p>Each investment cycle is governed by the plan terms displayed on the Earn page at the moment you join: investment amount, term length, earning schedule, and estimated total.</p><p>Your active and settled cycles, with their start and end dates, are always available on your Income page.</p>'},
complaints:{t:'Complaints procedure',b:'<p>If something is wrong, tell us through Submit a complaint on this page. Include your account email and as much detail as possible.</p><p>We acknowledge every complaint within 2 business days and aim to resolve them within 14 days. You will receive the outcome as a secure message and a notification.</p><p>If you are not satisfied with the outcome, you may reply to the secure message and ask for a senior review.</p>'}};
const HELP_FAQ=[['How do I deposit?','Open Home → Deposit and pay with mobile money or card.'],['When can I withdraw?','Any time your available balance covers the minimum; an admin approves each request.'],['What are CN coins?','Reward coins for sign-up, invites, tasks and campaigns. Withdrawable after TGE and CEX listing.'],['How do cycles work?','Pick a plan on Earn, invest, and receive earnings when the cycle settles at the end of its term.'],['I forgot my password','Log out and use the password reset on the login screen.']];
function showSupportModal(preset=''){showModal(preset||'Support center',`<p>Send us a secure message. We reply to your account email and in Secure messages.</p><form data-support-form class="support-form"><label>Subject<input name="subject" placeholder="What do you need help with?" value="${escapeHTML(preset)}" required></label><label>Message<textarea name="message" rows="4" placeholder="Describe your question..." required></textarea></label></form>${supportMessages.length?`<div class="support-history"><strong>Recent requests</strong>${supportMessages.slice(0,3).map(m=>`<div><span>${escapeHTML(m.subject)}</span><small>${notificationAge(m.createdAt)}</small></div>`).join('')}</div>`:''}`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-support">Send message</button>`);}
function showCycleDetail(name){ const c=earnPlans.find(x=>x.name===name); if(!c)return; const assetLabel=c.assets?c.assets.join(' · '):c.asset; const earningLabel=c.earning?`${moneyText(c.earning)} ${c.earningFrequency}`:'Variable'; const estimatedLabel=c.estimatedTotal?moneyText(c.estimatedTotal):'Not calculated'; showModal(c.name,`<div class="cycle-title" style="margin:8px 0 15px"><div class="coin ${c.asset==='ETH'?'eth':c.asset==='USDT'?'usdt':''}">${icon(c.asset)}</div><div><strong>${c.hot?'HOT · ':''}${assetLabel} · ${c.status}</strong><div class="helper">${c.description}</div></div></div><p>${c.description}</p>${cnPlanBadge(c)}<div class="detail-list"><div><span>Supported assets</span><strong>${assetLabel}</strong></div><div><span>Investment amount</span><strong>${moneyText(c.invest)}</strong></div><div><span>Earning schedule</span><strong>${earningLabel}</strong></div><div><span>Estimated earnings after cycle</span><strong>${estimatedLabel}</strong></div><div><span>Investment term</span><strong>${c.term}</strong></div>${c.maxInvestors>0?`<div><span>Investors</span><strong>${slotText(c)}${planFull(c)?' · Full':''}</strong></div>`:''}<div><span>Return calculation</span><strong>Calculated per cycle</strong></div><div><span>Withdrawal rules</span><strong>No early withdrawal</strong></div></div>`,`<button class="btn" data-action="back-to-earn">← Back to Earn</button><button class="btn" data-action="close-modal">Close</button>${planFull(c)?'<button class="btn primary" disabled>Plan full</button>':`<button class="btn primary" data-action="demo-invest" data-plan="${c.name}">Start investment</button>`}`); }
function navigateView(view){ if(view==='admin'&&!isAdmin){toast('Access denied','Administrator access is required.');return;} if(!['home','earn','cn','income','profile','admin'].includes(view)) view='home'; currentView=view; history.pushState({view},'',`#${view}`); render(); }
function render(){ document.body.classList.toggle('cn-mode',authState.authenticated&&currentView==='cn'); document.body.classList.toggle('auth-mode',!authState.authenticated); if(!authState.authenticated){ app.innerHTML=authState.loading?renderAuthLoading():renderAuth(); return; } settleEndedCycles(); app.innerHTML=currentView==='home'?renderHome():currentView==='earn'?renderEarn():currentView==='cn'?renderCN():currentView==='income'?renderIncome():currentView==='admin'&&isAdmin?renderAdmin():renderProfile(); document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===currentView));
  const rail=document.querySelector('.rail-nav'); if(rail){rail.querySelectorAll('[data-admin-nav]').forEach(x=>x.remove()); if(isAdmin) rail.insertAdjacentHTML('beforeend',adminNav().replace('data-nav="admin"','data-nav="admin" data-admin-nav="1"'));} const bottom=document.querySelector('.bottom-nav'); if(bottom){bottom.querySelectorAll('[data-admin-nav]').forEach(x=>x.remove()); if(isAdmin){bottom.insertAdjacentHTML('beforeend',adminNav().replace('nav-item ','mobile-nav-item ').replace('data-nav="admin"','data-nav="admin" data-admin-nav="1"'));bottom.style.gridTemplateColumns='repeat(6,1fr)';}else{bottom.style.gridTemplateColumns='';}} }

document.addEventListener('click',async e=>{ if(e.target.classList?.contains('modal-backdrop')){modalRoot.innerHTML='';return;} const authTab=e.target.closest('[data-auth-mode]'); if(authTab){authMode=authTab.dataset.authMode==='signup'?'signup':'login';authState.error='';render();return;} const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigateView(nav.dataset.nav);return;} const filter=e.target.closest('[data-filter]');if(filter){activeFilter=filter.dataset.filter;render();return;} const cycle=e.target.closest('[data-cycle]');if(cycle){showCycleDetail(cycle.dataset.cycle);return;} const actionEl=e.target.closest('[data-action]');const action=actionEl?.dataset.action;if(!action)return; if(action==='logout'){getSupabase()?.auth.signOut().finally(()=>{authState={loading:false,authenticated:false,user:null,error:''};render();});} else if(action==='terms'){e.preventDefault();showModal('Terms and conditions','<p>By using CRYPTONVA you agree to our terms of service.</p>');} else if(action==='notifications'){notificationOpen=!notificationOpen;render();} else if(action==='mark-all-read'){notifications=notifications.map(n=>({...n,unread:false}));saveNotifications();notificationOpen=true;render();} else if(action==='read-notification'){notifications=notifications.map(n=>n.id===actionEl.dataset.notificationId?{...n,unread:false}:n);saveNotifications();notificationOpen=true;render();} else if(action==='deposit'){const dc=defaultCountry();showModal('Deposit',`<p>Add funds with MTN, Airtel and other mobile money, or by card.</p><label class="demo-field">Pay with<select id="dep-method" class="input"><option value="mobile_money">Mobile money</option><option value="card">Card</option></select></label><label class="demo-field">Country<select id="dep-country" class="input">${countryOptions(dc)}</select></label><label class="demo-field" id="dep-phone-wrap">Mobile money number<input id="dep-phone" type="tel" inputmode="tel" placeholder="+${(MARZ_COUNTRIES.find(c=>c[0]===dc)||[])[3]}7XXXXXXXX" value="${escapeHTML(profile.phone||'')}"></label><label class="demo-field">Amount in <span id="dep-cur"></span><input id="dep-amount" type="number" min="1" step="1" inputmode="decimal" placeholder="10000"></label><div class="helper" id="dep-preview"></div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="demo-deposit">Pay now</button>`);updateDepositPreview();} else if(action==='withdraw'){const dc=defaultCountry();showModal('Request withdrawal',`<p>Withdrawals are sent to your mobile money after an administrator approves them.</p><label class="demo-field">Amount in USD<input id="withdraw-amount" type="number" min="${(appSettings.min_withdrawal_cents||0)/100}" step="0.01" placeholder="${((appSettings.min_withdrawal_cents||0)/100).toFixed(2)}"></label><label class="demo-field">Country<select id="withdraw-country" class="input">${countryOptions(dc)}</select></label><label class="demo-field">Mobile money number<input id="withdraw-destination" type="tel" inputmode="tel" placeholder="+${(MARZ_COUNTRIES.find(c=>c[0]===dc)||[])[3]}7XXXXXXXX" value="${escapeHTML(profile.phone||'')}"></label><div class="helper">Available balance: ${formatMoney(balances.available)} USD · Minimum ${((appSettings.min_withdrawal_cents||0)/100).toFixed(2)} USD</div>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-withdrawal">Submit request</button>`);} else if(action==='invite'){const code=referralStats?.code||'';showModal('Invite friends',`<div class="invite-code" style="margin-bottom:10px"><span>Invitation code: <strong>${escapeHTML(referralStats?.code||'')}</strong></span><button class="btn small" data-action="copy-code">Copy</button></div><p>Share your code — friends enter it in the "Invitation code" field when signing up. You earn <strong>${((referralStats?.bonus_cents||0)/100).toFixed(2)} USD</strong> when a friend you invited makes their first deposit.</p><div class="meta-grid" style="margin-top:14px"><div><span class="meta-label">Joined</span><span class="meta-value">${referralStats?.count||0}</span></div><div><span class="meta-label">Deposited</span><span class="meta-value">${referralStats?.rewarded||0}</span></div><div><span class="meta-label">Earned</span><span class="meta-value">${((referralStats?.earned_cents||0)/100).toFixed(2)} USD</span></div></div>`,`<button class="btn whatsapp-btn" data-action="share-promo">WhatsApp · earn 2000 CN</button><button class="btn" data-action="ai-invite">✦ Write invite with AI</button><button class="btn" data-action="close-modal">Close</button>`);} else if(action==='copy-code'){navigator.clipboard?.writeText(referralStats?.code||'');toast('Invitation code copied','Friends can enter it when signing up.');} else if(action==='wallet-info'){showModal('CRYPTONVA wallet','<p>Your CRYPTONVA wallet identity.</p>');} else if(action==='coming-soon'){showModal('Coming soon','<p>Reports will be available soon.</p>');} else if(action==='demo-invest'){addDemoCycle(actionEl.dataset.plan);} else if(action==='demo-deposit'){addDemoDeposit();} else if(action==='submit-withdrawal'){(async()=>{const amount=Number(document.querySelector('#withdraw-amount')?.value||0),phoneRaw=String(document.querySelector('#withdraw-destination')?.value||'').replace(/[\s-]/g,''),destination=phoneRaw?`${document.querySelector('#withdraw-country')?.value||'UG'}:+${phoneRaw.replace(/^\+/,'')}`:'',cents=Math.round(amount*100);if(cents<(appSettings.min_withdrawal_cents||0)){toast('Amount too low',`Minimum withdrawal is ${((appSettings.min_withdrawal_cents||0)/100).toFixed(2)} USD.`);return;}if(!Number.isFinite(cents)||cents<=0||!destination){toast('Withdrawal incomplete','Enter a valid amount and destination.');return;}if(cents>Math.round(Number(balances.available)*100)){toast('Insufficient balance','The requested amount exceeds your available balance.');return;}const sb=getSupabase();const {data:acct}=await sb.from('accounts').select('id').eq('user_id',authState.user.id).maybeSingle();if(!acct?.id){toast('Account unavailable','Your financial account could not be found.');return;}const {error}=await sb.from('withdrawal_requests').insert({user_id:authState.user.id,account_id:acct.id,amount_cents:cents,destination});if(error){toast('Request failed',error.message);return;}modalRoot.innerHTML='';await refreshAccount();toast('Withdrawal requested','Your request is now waiting for administrator review.');})();} else if(action==='support-topic'){const subject=document.querySelector('[data-support-form] input[name=subject]');if(subject){subject.value=actionEl.dataset.topic||'';subject.focus();}} else if(action==='submit-support'){document.querySelector('[data-support-form]')?.requestSubmit();} else if(action==='reset-balances'){resetDemoBalances();} else if(action==='back-to-earn'){modalRoot.innerHTML='';navigateView('earn');} else if(action==='support'){showModal('Support center',`<p>Find quick answers or send a support request.</p><div class="support-topic-grid"><button class="support-topic" data-action="support-topic" data-topic="Account and profile">Account & profile</button><button class="support-topic" data-action="support-topic" data-topic="Deposits and balances">Deposits & balances</button><button class="support-topic" data-action="support-topic" data-topic="Investment cycles">Investment cycles</button><button class="support-topic" data-action="support-topic" data-topic="Income and returns">Income & returns</button></div><form data-support-form class="support-form"><label>Subject<input name="subject" placeholder="What do you need help with?" required></label><label>Message<textarea name="message" rows="4" placeholder="Describe your question..." required></textarea></label></form>${supportMessages.length?`<div class="support-history"><strong>Recent requests</strong>${supportMessages.slice(0,3).map(m=>`<div><span>${escapeHTML(m.subject)}</span><small>${notificationAge(m.createdAt)}</small></div>`).join('')}</div>`:''}`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-support">Send message</button>`);} else if(action==='admin-refresh'){await refreshAdmin();render();} else if(action==='change-password'){showModal('Change password',`<p>Choose a new password for your CRYPTONVA account. You will use it the next time you log in.</p><form data-pw-form class="support-form"><label>New password<input name="password" type="password" minlength="8" autocomplete="new-password" placeholder="At least 8 characters" required></label><label>Confirm new password<input name="confirm" type="password" minlength="8" autocomplete="new-password" placeholder="Repeat the new password" required></label></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-pw">Update password</button>`);} else if(action==='submit-pw'){document.querySelector('[data-pw-form]')?.requestSubmit();} else if(action==='withdrawal-pin'){showModal('Withdrawal PIN',`<p>This PIN protects your withdrawal requests. Use 4–6 digits and keep it private.</p><form data-pin-form class="support-form"><label>${profileSecurity.pin?'New PIN':'Create PIN'}<input name="pin" type="password" inputmode="numeric" pattern="[0-9]{4,6}" maxlength="6" placeholder="4–6 digits" required></label><label>Confirm PIN<input name="confirm" type="password" inputmode="numeric" pattern="[0-9]{4,6}" maxlength="6" placeholder="Repeat the PIN" required></label></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-pin">Save PIN</button>`);} else if(action==='submit-pin'){document.querySelector('[data-pin-form]')?.requestSubmit();} else if(action==='mfa'){const sb=getSupabase();const {data}=await sb.auth.mfa.listFactors();const verified=(data?.totp||[]).filter(f=>f.status==='verified');if(verified.length){showModal('Multi-factor authentication',`<p>MFA is <strong>enabled</strong> on this account. Your authenticator app generates a code at each login.</p>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn" data-action="mfa-disable" data-factor="${verified[0].id}">Disable MFA</button>`);}else{const {data:en,error}=await sb.auth.mfa.enroll({factorType:'totp',friendlyName:'CRYPTONVA'});if(error){toast('MFA unavailable',error.message);return;}showModal('Enable MFA',`<p>Scan this code with an authenticator app (Google Authenticator, Authy…), then enter the 6-digit code it shows.</p><div class="mfa-qr">${en.totp.qr_code}</div><form data-mfa-form="${en.id}" class="support-form"><label>6-digit code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required></label></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" data-action="submit-mfa">Verify & enable</button>`);}} else if(action==='submit-mfa'){document.querySelector('[data-mfa-form]')?.requestSubmit();} else if(action==='mfa-disable'){const sb=getSupabase();const {error}=await sb.auth.mfa.unenroll({factorId:actionEl.dataset.factor});if(error){toast('Could not disable',error.message);return;}profileSecurity.mfa=false;modalRoot.innerHTML='';render();toast('MFA disabled','Multi-factor authentication was turned off.');} else if(action==='login-history'||action==='devices'){const sb=getSupabase();const {data,error}=await sb.rpc('my_login_events');if(error){toast('Could not load',error.message);return;}const rows=data||[];if(action==='login-history'){showModal('Login history',rows.length?`<div class="detail-list">${rows.map(r=>`<div><span>${escapeHTML(r.device)}</span><strong>${new Date(r.created_at).toLocaleString()}</strong></div>`).join('')}</div>`:'<p>No sign-ins recorded yet.</p>');}else{const seen=new Map();rows.forEach(r=>{if(!seen.has(r.device))seen.set(r.device,r.created_at)});const cur=deviceLabel();showModal('Active devices',`<p>Devices that have signed in to your account. If you see one you do not recognize, change your password immediately.</p><div class="detail-list"><div><span>${escapeHTML(cur)}</span><strong>This device · now</strong></div>${[...seen.entries()].filter(([d])=>d!==cur).map(([d,t])=>`<div><span>${escapeHTML(d)}</span><strong>Last seen ${new Date(t).toLocaleString()}</strong></div>`).join('')}</div>`);}} else if(action==='doc'){const d=DOC_TEXTS[actionEl.dataset.doc];if(d)showModal(d.t,d.b);} else if(action==='help-center'){showModal('Help center',`<div class="detail-list">${HELP_FAQ.map(f=>`<div><span>${escapeHTML(f[0])}</span><strong style="font-weight:400">${escapeHTML(f[1])}</strong></div>`).join('')}</div>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="contact-support">Contact support</button>`);} else if(action==='contact-support'){showSupportModal('');} else if(action==='complaint'){showSupportModal('Complaint');} else if(action==='report'){showSupportModal('Suspicious activity report');} else if(action==='secure-messages'){showModal('Secure messages',supportMessages.length?`<div class="detail-list">${supportMessages.map(m=>`<div><span>${escapeHTML(m.subject)}</span><strong>${notificationAge(m.createdAt)}</strong></div>`).join('')}</div>`:'<p>No messages yet. Use Contact support to reach us.</p>');} else if(action==='change-photo'){document.querySelector('#avatar-file')?.click();} else if(action==='close-modal'){modalRoot.innerHTML='';} });

document.addEventListener('click',async e=>{
 const ast=e.target.closest('[data-admin-setting]'); if(ast){const k=ast.dataset.adminSetting;const v=prompt('New amount in USD:',((appSettings[k]||0)/100).toFixed(2));if(v===null)return;const n=Number(v);if(!(n>=0)){toast('Invalid amount','Enter a number.');return;}const {error}=await getSupabase().rpc('admin_set_setting',{p_key:k,p_value:Math.round(n*100)});if(error)toast('Save failed',error.message);else{await loadMoneySettings();render();toast('Saved','Setting updated.');}return;}
 const afx=e.target.closest('[data-admin-fx]'); if(afx){const c=afx.dataset.adminFx;const v=prompt(`How many ${c} equal 1 USD?`,fxRates[c]);if(v===null)return;const n=Number(v);if(!(n>0)){toast('Invalid rate','Enter a positive number.');return;}const {error}=await getSupabase().rpc('admin_set_fx',{p_currency:c,p_rate:n});if(error)toast('Save failed',error.message);else{await loadMoneySettings();render();toast('Saved',`${c} rate updated.`);}return;}
 const pm=e.target.closest('[data-plan-move]'); if(pm){movePlan(pm.dataset.planMove,parseInt(pm.dataset.pos,10));return;} const pe=e.target.closest('[data-plan-edit]'); if(pe){const p=adminCache.plans.find(x=>x.id===pe.dataset.planEdit)||{name:'',asset:'BTC',category:'Short term',invest:'',earning:'',estimatedTotal:'',termDays:14,status:'Open',hot:false,risk:'Medium',network:'',description:'',active:true,sortOrder:adminCache.plans.length+1};const f=(n,l,v,t='text')=>`<label class="field"><span>${l}</span><input class="input" name="${n}" type="${t}" ${t==='number'?'step="0.01" min="0"':''} value="${escapeHTML(String(v??''))}" ${n==='network'?'':'required'}></label>`;const sel=(n,l,v,opts)=>`<label class="field"><span>${l}</span><select class="input" name="${n}">${opts.map(o=>`<option ${o===v?'selected':''}>${o}</option>`).join('')}</select></label>`;showModal(p.id?'Edit plan':'Add plan',`<form data-plan-form="${p.id||''}" id="plan-form" style="display:grid;gap:10px;max-height:60vh;overflow-y:auto;padding-right:4px">${f('name','Plan name',p.name)}${sel('asset','Asset',p.asset,['BTC','ETH','LTC','USDT'])}${sel('category','Category',p.category,['Short term','Long term'])}${f('invest','Invest amount (USDT)',p.invest,'number')}${f('roi_percent','Daily ROI (% of invest amount)',p.roiPercent||(p.invest>0?(p.earning/p.invest*100).toFixed(2):''),'number')}${f('term_days','Cycle length (days)',p.termDays,'number')}<div class="helper" id="roi-preview" style="padding:8px 10px;border:1px dashed var(--line);border-radius:10px">Set invest amount, ROI % and term to preview the member-facing earnings.</div>${sel('status','Label',p.status,['Open','Hot','Closed'])}${sel('risk','Risk',p.risk,['Low','Medium','High'])}${f('network','Network',p.network)}<label class="field"><span>Description</span><textarea class="input" name="description">${escapeHTML(p.description||'')}</textarea></label>${f('cn_reward','CN reward per investment (0 = none)',p.cnReward||0,'number')}${f('max_investors','Investor limit (0 = no limit)',p.maxInvestors||0,'number')}${f('sort_order','Display order',p.sortOrder,'number')}<label><input type="checkbox" name="hot" ${p.hot?'checked':''}> Highlight as hot</label><label><input type="checkbox" name="active" ${p.active?'checked':''}> Visible to users</label></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" form="plan-form">Save plan</button>`);return;}
 const ant=e.target.closest('[data-admin-nav-toggle]'); if(ant){adminNavCollapsed=!adminNavCollapsed;try{localStorage.setItem('cryptonva_admin_nav',adminNavCollapsed?'1':'0')}catch(_){ }render();return;}
 const sec=e.target.closest('[data-admin-section]'); if(sec){adminSection=sec.dataset.adminSection;await refreshAdmin();render();return;}
 const au=e.target.closest('[data-admin-user]'); if(au){const next=au.dataset.adminStatus;const reason=prompt('Reason for this account action:');if(!reason)return;const {error}=await getSupabase().rpc('admin_set_user_restriction',{p_user_id:au.dataset.adminUser,p_status:next,p_reason:reason});if(error)toast('Action failed',error.message);else toast('Account updated',`User ${next}.`);await refreshAdmin();render();return;}
 const ap=e.target.closest('[data-withdraw-approve]'); if(ap){if(!confirm('Approve and send this withdrawal to the user\'s mobile money now?'))return;ap.disabled=true;try{const r=await apiCall('/api/public/payments/payout',{method:'POST',body:JSON.stringify({request_id:ap.dataset.withdrawApprove})});toast('Withdrawal approved',`Sending ${Number(r.local_amount).toLocaleString()} ${r.currency} via Marz.`);}catch(err){toast('Payout failed',err.message);}await refreshAdmin();render();return;}
 const rr=e.target.closest('[data-withdraw-reject]'); if(rr){const note=prompt('Reason for rejecting this withdrawal:');if(!note)return;const {error}=await getSupabase().rpc('admin_review_withdrawal',{p_request_id:rr.dataset.withdrawReject,p_status:'rejected',p_note:note});if(error)toast('Rejection failed',error.message);else toast('Withdrawal rejected','The decision was recorded.');await refreshAdmin();render();return;}
 const paid=e.target.closest('[data-withdraw-paid]'); if(paid){if(!confirm('Confirm that this withdrawal was actually paid through the connected payment rail?'))return;const {error}=await getSupabase().rpc('admin_mark_withdrawal_paid',{p_request_id:paid.dataset.withdrawPaid});if(error)toast('Could not mark paid',error.message);else toast('Marked paid','The ledger and audit trail were updated.');await refreshAdmin();render();return;}
 const ka=e.target.closest('[data-kyc-approve]'); if(ka){const {error}=await getSupabase().rpc('admin_review_kyc',{p_review_id:ka.dataset.kycApprove,p_status:'approved',p_reason:null});if(error)toast('KYC approval failed',error.message);else toast('KYC approved','Compliance decision recorded.');await refreshAdmin();render();return;}
 const kr=e.target.closest('[data-kyc-reject]'); if(kr){const reason=prompt('Reason for rejecting KYC:');if(!reason)return;const {error}=await getSupabase().rpc('admin_review_kyc',{p_review_id:kr.dataset.kycReject,p_status:'rejected',p_reason:reason});if(error)toast('KYC rejection failed',error.message);else toast('KYC rejected','Compliance decision recorded.');await refreshAdmin();render();return;}
});

document.addEventListener('change',e=>{if(e.target.closest?.('#dep-method,#dep-country'))updateDepositPreview();});

document.addEventListener('input',e=>{if(e.target.id==='dep-amount')updateDepositPreview();const q=e.target.closest?.('[data-admin-user-search]');if(!q)return;adminUserQuery=q.value.trim();const v=adminUserQuery.toLowerCase();document.querySelectorAll('[data-user-row]').forEach(r=>{r.style.display=!v||r.dataset.userRow.includes(v)?'':'none';});});
document.addEventListener('input',e=>{ const form=e.target.closest('#plan-form'); if(!form)return; const prev=document.getElementById('roi-preview'); if(!prev)return; const d=new FormData(form); const inv=Number(d.get('invest'))||0, roi=Number(d.get('roi_percent'))||0, days=Math.max(1,parseInt(d.get('term_days'),10)||0); if(inv>0&&roi>0&&days>0){const perDay=inv*roi/100;prev.innerHTML=`Members will see: <strong>${moneyText(perDay.toFixed(2))} per day</strong> · estimated <strong>${moneyText((perDay*days).toFixed(2))}</strong> total profit over ${days} days.`;}else{prev.textContent='Set invest amount, ROI % and term to preview the member-facing earnings.';} });
document.addEventListener('submit',async e=>{ const pf=e.target.closest('[data-plan-form]'); if(pf){e.preventDefault();const d=new FormData(pf);const row={name:String(d.get('name')).trim().slice(0,80),asset:d.get('asset'),category:d.get('category'),invest:Number(d.get('invest')),roi_percent:Math.max(0,Number(d.get('roi_percent'))||0),term_days:Math.max(1,parseInt(d.get('term_days'),10)||14),status:d.get('status'),risk:d.get('risk'),network:String(d.get('network')||'').slice(0,60),description:String(d.get('description')||'').slice(0,500),sort_order:parseInt(d.get('sort_order'),10)||0,max_investors:Math.max(0,parseInt(d.get('max_investors'),10)||0),cn_reward:Math.max(0,Number(d.get('cn_reward'))||0),hot:d.get('hot')==='on',active:d.get('active')==='on',updated_at:new Date().toISOString()};row.earning=+(row.invest*row.roi_percent/100).toFixed(2);row.estimated_total=+(row.earning*row.term_days).toFixed(2);if(!row.name||!(row.invest>0)||!(row.roi_percent>0)){toast('Check the form','Name, invest amount and a daily ROI % are required.');return;}const sb=getSupabase();const id=pf.dataset.planForm;const {error}=id?await sb.from('investment_plans').update(row).eq('id',id):await sb.from('investment_plans').insert(row);if(error){toast('Save failed',error.message);return;}modalRoot.innerHTML='';await loadPlans();await refreshAdmin();render();toast('Plan saved',`${row.name} is updated.`);return;} const authForm=e.target.closest('[data-auth-form]'); if(authForm){ e.preventDefault(); const data=new FormData(authForm); const payload=Object.fromEntries(data.entries()); payload.terms=Boolean(data.get('terms')); if(authMode==='signup'&&payload.password!==payload.confirmPassword){authState.error='Passwords do not match.';render();return;} if(authMode==='signup'&&!payload.terms){authState.error='You must accept the Terms and Conditions to create an account.';render();return;} authState.error=''; const button=authForm.querySelector('button[type=submit]'); if(button){button.disabled=true;button.textContent=authMode==='signup'?'Creating account…':'Logging in…';} try { const sb=getSupabase(); if(!sb) throw new Error('Authentication service is still loading. Please try again.'); let result; if(authMode==='signup'){ const {data,error}=await sb.auth.signUp({email:payload.email,password:payload.password,options:{data:{username:payload.username,phone:payload.telecom,country:payload.country,ref:(String(payload.inviteCode||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'')||undefined)}}}); if(error)throw error; if(!data.session) throw new Error('Account created. Please check your email to confirm your address before signing in.'); result=data; } else { const {data,error}=await sb.auth.signInWithPassword({email:payload.email,password:payload.password}); if(error)throw error; result=data; } authState={loading:false,authenticated:Boolean(result.session),user:result.user,error:''}; profile={...profile,name:result.user.user_metadata?.username||profile.name,email:result.user.email||profile.email,phone:result.user.user_metadata?.phone||profile.phone,country:result.user.user_metadata?.country||profile.country}; sb.rpc('record_login_event',{_device:deviceLabel()}).then(()=>{},()=>{}); await refreshAccount(); render(); toast(authMode==='signup'?'Account created':'Welcome back',`You are now signed in to CRYPTONVA.`); } catch(error){authState={loading:false,authenticated:false,user:null,error:error.message||'Account request failed.'};render();} return; } const supportForm=e.target.closest('[data-support-form]'); if(supportForm){ e.preventDefault(); const data=new FormData(supportForm); const subject=String(data.get('subject')||'').trim(), message=String(data.get('message')||'').trim(); if(!subject||!message){toast('Support message incomplete','Add a subject and message before sending.');return;} const sb=getSupabase();const {error}=await sb.from('support_messages').insert({user_id:authState.user.id,subject,message});if(error){toast('Could not send request',error.message);return;}modalRoot.innerHTML='';await refreshAccount();toast('Support request received','Your request was recorded securely.');return; } const form=e.target.closest('[data-profile-form]');if(!form)return;e.preventDefault();const data=new FormData(form);profile={name:String(data.get('name')||'').trim(),email:String(data.get('email')||'').trim(),phone:String(data.get('phone')||'').trim(),country:String(data.get('country')||'').trim(),timezone:String(data.get('timezone')||'').trim()};if(!profile.name||!profile.email){toast('Profile incomplete','Full name and a valid email are required.');return;}const sb=getSupabase();const {error}=await sb.from('profiles').update({full_name:profile.name,phone:profile.phone,country:profile.country,timezone:profile.timezone,updated_at:new Date().toISOString()}).eq('id',authState.user.id);if(error){toast('Profile not saved',error.message);return;}render();toast('Profile saved','Your profile was saved securely.'); });

if(['home','earn','cn','income','profile','admin'].includes(location.hash.slice(1))) currentView=location.hash.slice(1);
async function initAuth(){ render(); try { const sb=getSupabase(); if(!sb) throw new Error('Authentication service is unavailable.'); const {data:{session}}=await sb.auth.getSession(); const u=session?.user||null; authState={loading:false,authenticated:Boolean(u),user:u,error:''}; if(u){profile={...profile,name:u.user_metadata?.username||profile.name,email:u.email||profile.email,phone:u.user_metadata?.phone||profile.phone,country:u.user_metadata?.country||profile.country};sb.rpc('record_login_event',{_device:deviceLabel()}).then(()=>{},()=>{});await refreshAccount();await refreshAdmin();} sb.auth.onAuthStateChange(async (_event,nextSession)=>{const user=nextSession?.user||null;authState={loading:false,authenticated:Boolean(user),user,error:''};if(user){profile={...profile,name:user.user_metadata?.username||profile.name,email:user.email||profile.email,phone:user.user_metadata?.phone||profile.phone,country:user.user_metadata?.country||profile.country};await refreshAccount();await refreshAdmin();}else{isAdmin=false;}render();}); } catch(error){ authState={loading:false,authenticated:false,user:null,error:error.message||'Authentication service is unavailable.'}; } render(); }
initAuth();
setInterval(updateCountdowns,1000);
window.addEventListener('popstate',()=>{const view=history.state?.view||location.hash.slice(1)||'home';currentView=['home','earn','cn','income','profile','admin'].includes(view)&&(!isAdmin&&view==='admin'?false:true)?view:'home';render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalRoot.innerHTML){modalRoot.innerHTML='';}});

function toast(title,body){const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.innerHTML=`<strong>${escapeHTML(title)}</strong>${escapeHTML(body||'')}`;document.body.appendChild(el);setTimeout(()=>el.remove(),3500);}

async function movePlan(id,pos){if(!(pos>=1))return;const {error}=await getSupabase().rpc('admin_move_plan',{p_plan_id:id,p_position:pos});if(error){toast('Move failed',error.message);return;}await loadPlans();await refreshAdmin();render();toast('Order updated',`Plan moved to position ${pos}.`);}
document.addEventListener('change',e=>{const i=e.target.closest&&e.target.closest('[data-plan-pos]');if(i)movePlan(i.dataset.planPos,parseInt(i.value,10));});

// ---- CN tasks, campaigns & leaderboards ----
let cnAdmin={tasks:[],campaigns:[],subs:[]};const cnOpened=new Set();
function cnSafeLink(u){u=String(u||'').trim();return /^https?:\/\//i.test(u)?u:'';}
function cnPrizeText(c,p){return c.prize_type==='cash'?`${Number(p).toLocaleString('en-US',{minimumFractionDigits:2})} USD`:`${Number(p).toLocaleString('en-US')} CN`;}
function cnEnded(c){return new Date(c.ends_at).getTime()<=Date.now()||c.status==='paid';}
function cnProofForm(attr,id){return `<form class="cn-proof-form" ${attr}="${id}"><input class="input" name="proof" placeholder="Paste proof link or describe what you did" maxlength="1000" required><button class="btn primary small" type="submit">Submit proof</button></form>`;}
function cnOpenBtn(id,link){const l=cnSafeLink(link);if(!l)return '';return cnOpened.has(id)?'':`<button class="btn small" data-cn-open="${id}" data-link="${escapeHTML(l)}">Open challenge ↗</button>`;}
function renderCNEarn(){
 const b=cnBoard||{tasks:[],campaigns:[]};
 const task=t=>{let action='';if(t.kind==='invest'){action=`<small class="cn-caption">Start ${escapeHTML(cnPlanNames(t.plan_ids))} · no expiry</small>${t.claimed?'<span class="cn-status ok">Reward received</span>':t.eligible?`<button class="btn primary small" data-cn-claim="${t.id}">Claim ${Number(t.reward_coins).toLocaleString()} CN</button>`:'<button class="btn primary small" data-action="back-to-earn">Go to Earn plans</button>'}`;}
   else if(t.kind==='invite'){const prog=Math.min(Number(t.progress??b.invite_progress??0),t.invite_target);const rem=Math.max(0,Number(t.remaining??(t.invite_target-prog)));action=`<div class="cn-progress"><i style="width:${t.invite_target?Math.round(prog/t.invite_target*100):0}%"></i></div><small class="cn-caption">${prog}/${t.invite_target} friends invested · ${rem} remaining</small>${t.claimed?'<span class="cn-status ok">Reward received automatically</span>':`<button class="btn primary small" data-action="invite">Start inviting</button>`}`;}
  else if(t.claimed||t.my_status==='approved')action='<span class="cn-status ok">Approved · reward received</span>';
  else if(t.my_status==='pending')action='<span class="cn-status">Proof under review</span>';
  else action=`${t.my_status==='rejected'?'<span class="cn-status bad">Proof rejected · try again</span>':''}${cnOpenBtn(t.id,t.link)}${(!cnSafeLink(t.link)||cnOpened.has(t.id))?cnProofForm('data-cn-task-proof',t.id):''}`;
  return `<article class="cn-item"><div class="cn-item-head"><strong>${escapeHTML(t.title)}</strong><span class="cn-asset-badge">+${Number(t.reward_coins).toLocaleString()} CN</span></div><p>${escapeHTML(t.description)}</p>${action}</article>`;};
 const camp=c=>{const ended=cnEnded(c);const used=Number(c.my_approved)+Number(c.my_pending);const prizes=(c.prizes||[]).map((p,i)=>`<span>#${i+1} ${cnPrizeText(c,p)}</span>`).join('');
  const leaders=(c.leaders||[]).map((l,i)=>`<li class="${l.me?'me':''}"><span>#${i+1} ${escapeHTML(l.name)}${l.me?' (you)':''}</span><strong>${l.score}</strong></li>`).join('')||'<li><span class="helper">No approved entries yet</span></li>';
  if(c.kind==='invest'){const tgt=Number(c.invest_target)||1,n=Math.min(Number(c.my_invest_count||0),tgt),per=Number(c.reward_coins)/tgt;const act=ended?`<span class="cn-status">${c.status==='paid'?'Ended · prizes paid':'Ended'}</span>`:n>=tgt?'<span class="cn-status ok">Target reached · all rewards received</span>':'<button class="btn primary small" data-action="back-to-earn">Invest in a plan</button>';return `<article class="cn-item"><div class="cn-item-head"><strong>${escapeHTML(c.title)}</strong><span class="cn-asset-badge">${ended?'Ended':'+'+Number(c.reward_coins).toLocaleString()+' CN'}</span></div><p>${escapeHTML(c.description)}</p><div class="cn-progress"><i style="width:${Math.round(n/tgt*100)}%"></i></div><small class="cn-caption">${n}/${tgt} investment plans · +${per.toLocaleString(undefined,{maximumFractionDigits:2})} CN per plan · ${escapeHTML(cnPlanNames(c.plan_ids))}${ended?'':' · ends '+new Date(c.ends_at).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</small>${prizes?`<div class="cn-prizes">${prizes}</div>`:''}<h4 class="cn-lb-title">Leaderboard</h4><ol class="cn-leaders">${leaders}</ol>${act}</article>`;}
   const cap=Number(c.max_total_entries||0),full=cap>0&&Number(c.total_entries)>=cap;let action=ended?`<span class="cn-status">${c.status==='paid'?'Ended · prizes paid':'Ended · prizes pending'}</span>`:full?'<span class="cn-status bad">Campaign full · no new entries</span>':used>=c.max_participations?'<span class="cn-status">Participation limit reached</span>':`${cnOpenBtn(c.id,c.link)}${(!cnSafeLink(c.link)||cnOpened.has(c.id))?cnProofForm('data-cn-camp-proof',c.id):''}`;
  return `<article class="cn-item"><div class="cn-item-head"><strong>${escapeHTML(c.title)}</strong><span class="cn-asset-badge">${ended?'Ended':full?'Full':'Ends '+new Date(c.ends_at).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div><p>${escapeHTML(c.description)}</p><div class="cn-prizes">${prizes}</div><small class="cn-caption">Your entries: ${c.my_approved} approved · ${c.my_pending} pending · limit ${c.max_participations}${cap>0?` · ${Math.min(c.total_entries,cap)}/${cap} total entries`:''}</small><h4 class="cn-lb-title">Leaderboard</h4><ol class="cn-leaders">${leaders}</ol>${action}</article>`;};
 return `<section class="section"><div class="section-heading"><h2>Tasks</h2>${cnSymbol('task')}</div><div class="cn-items">${(b.tasks||[]).map(task).join('')||'<p class="helper">No active tasks right now.</p>'}</div></section>
 <section class="section"><div class="section-heading"><h2>Campaigns</h2>${cnSymbol('campaign')}</div><div class="cn-items">${(b.campaigns||[]).map(camp).join('')||'<p class="helper">No campaigns right now.</p>'}</div></section>`;
}
async function loadAdminCN(){const sb=getSupabase();try{const [t,c,s]=await Promise.all([sb.from('cn_tasks').select('*').order('created_at',{ascending:false}),sb.from('cn_campaigns').select('*').order('created_at',{ascending:false}),sb.rpc('admin_list_cn_submissions')]);cnAdmin={tasks:t.data||[],campaigns:c.data||[],subs:s.data||[]};}catch(e){console.warn('CN admin load failed',e);}}
function renderAdminCN(){
 const subs=cnAdmin.subs.map(x=>`<tr><td>${escapeHTML(x.email)}</td><td>${escapeHTML(x.kind)} · ${escapeHTML(x.item)}</td><td style="max-width:280px;word-break:break-word">${cnSafeLink(x.proof)?`<a href="${escapeHTML(x.proof)}" target="_blank" rel="noopener noreferrer">${escapeHTML(x.proof)}</a>`:escapeHTML(x.proof)}</td><td>${escapeHTML(x.status)}</td><td>${x.status==='pending'?`<button class="btn small primary" data-cn-review="${x.id}" data-status="approved">Approve</button> <button class="btn small" data-cn-review="${x.id}" data-status="rejected">Reject</button>`:new Date(x.created_at).toLocaleDateString()}</td></tr>`).join('')||'<tr><td colspan="5">No submissions yet.</td></tr>';
 const tasks=cnAdmin.tasks.map(t=>`<tr><td>${escapeHTML(t.title)}</td><td>${t.kind==='invite'?`Invite ${t.invite_target} investors`:t.kind==='invest'?`Earn plans · ${escapeHTML(cnPlanNames(t.plan_ids))}`:'Social · proof'}</td><td>${Number(t.reward_coins).toLocaleString()} CN</td><td>${t.active?'Visible':'Hidden'}</td><td><button class="btn small" data-cn-task-edit="${t.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="5">No tasks yet.</td></tr>';
 const camps=cnAdmin.campaigns.map(c=>`<tr><td>${escapeHTML(c.title)}</td><td>${new Date(c.ends_at).toLocaleString()}</td><td>${c.kind==='invest'?`${Number(c.reward_coins).toLocaleString()} CN over ${c.invest_target} plans`:''}${c.kind==='invest'&&(c.prizes||[]).length?' + ':''}${(c.prizes||[]).map((p,i)=>`#${i+1} ${cnPrizeText(c,p)}`).join(', ')}</td><td>${escapeHTML(c.status)}${c.max_total_entries>0?` · cap ${c.max_total_entries}`:''}</td><td>${c.status==='paid'?'Paid':`<button class="btn small" data-cn-camp-edit="${c.id}">Edit</button>${new Date(c.ends_at).getTime()<=Date.now()?` <button class="btn small primary" data-cn-pay="${c.id}">Pay winners</button>`:''}`}</td></tr>`).join('')||'<tr><td colspan="5">No campaigns yet.</td></tr>';
 return `<div class="admin-panel card"><div class="admin-heading"><div><h2>Proof reviews</h2><p>Approving a task proof grants its CN reward. Approved campaign proofs add +1 on the leaderboard.</p></div><button class="btn" data-action="admin-refresh">Refresh</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>User</th><th>For</th><th>Proof</th><th>Status</th><th>Action</th></tr></thead><tbody>${subs}</tbody></table></div></div>
 <div class="admin-panel card"><div class="admin-heading"><div><h2>Tasks</h2><p>One-time tasks. Invite tasks count only invited friends who invested in a plan.</p></div><button class="btn primary" data-cn-task-edit="new">Add task</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Title</th><th>Type</th><th>Reward</th><th>Status</th><th></th></tr></thead><tbody>${tasks}</tbody></table></div></div>
 <div class="admin-panel card"><div class="admin-heading"><div><h2>Campaigns & leaderboards</h2><p>After the end date, press Pay winners to send each rank its prize.</p></div><button class="btn primary" data-cn-camp-edit="new">Add campaign</button></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>Title</th><th>Ends</th><th>Prize pool</th><th>Status</th><th></th></tr></thead><tbody>${camps}</tbody></table></div></div>`;
}
function cnPlanBadge(c){return c.cnReward>0?`<div class="plan-cn-reward"><img src="${CN_COIN_URL}" alt="CN coin"><div><strong>+${Number(c.cnReward).toLocaleString()} CN reward</strong><span>Worth ${moneyText((c.cnReward*0.48).toFixed(2))} · added when you start</span></div></div>`:'';}
function cnPlanPick(sel){const ids=new Set(sel||[]);const plans=(adminCache.plans&&adminCache.plans.length?adminCache.plans:earnPlans).filter(p=>p.id);return `<fieldset class="field"><span>Linked earn plans (none ticked = any plan)</span><div style="display:grid;gap:4px;max-height:140px;overflow-y:auto">${plans.map(p=>`<label><input type="checkbox" name="plan_ids" value="${p.id}" ${ids.has(p.id)?'checked':''}> ${escapeHTML(p.name)}</label>`).join('')}</div></fieldset>`;}
function cnPlanNames(ids){if(!ids||!ids.length)return 'any earn plan';return ids.map(id=>(earnPlans.find(p=>p.id===id)||{}).name).filter(Boolean).join(', ')||'selected plans';}
function cnField(n,l,v,t='text',extra=''){return `<label class="field"><span>${l}</span><input class="input" name="${n}" type="${t}" value="${escapeHTML(v??'')}" ${extra}></label>`;}
function cnLocalDT(iso){const d=iso?new Date(iso):new Date(Date.now()+7*86400000);const p=x=>String(x).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;}
document.addEventListener('click',async e=>{
 const sb=getSupabase();
 const op=e.target.closest('[data-cn-open]');if(op){window.open(op.dataset.link,'_blank','noopener,noreferrer');cnOpened.add(op.dataset.cnOpen);render();return;}
 const cl=e.target.closest('[data-cn-claim]');if(cl){const {error}=await sb.rpc('cn_claim_invite_task',{p_task:cl.dataset.cnClaim});if(error){toast('Not yet',error.message);return;}await loadCNRewards();render();toast('Reward added','Your CN task reward was added.');return;}
 const rv=e.target.closest('[data-cn-review]');if(rv){const {error}=await sb.rpc('admin_review_cn_submission',{p_id:rv.dataset.cnReview,p_status:rv.dataset.status});if(error){toast('Review failed',error.message);return;}await loadAdminCN();render();toast('Saved',`Proof ${rv.dataset.status}.`);return;}
 const pay=e.target.closest('[data-cn-pay]');if(pay){if(!confirm('Pay prizes to the top leaderboard ranks now? This cannot be undone.'))return;const {data,error}=await sb.rpc('admin_pay_cn_campaign',{p_campaign:pay.dataset.cnPay});if(error){toast('Payout failed',error.message);return;}await loadAdminCN();render();toast('Winners paid',`${data||0} prize(s) sent.`);return;}
 const te=e.target.closest('[data-cn-task-edit]');if(te){const t=cnAdmin.tasks.find(x=>x.id===te.dataset.cnTaskEdit)||{kind:'social',active:true,reward_coins:1000,invite_target:100};showModal(t.id?'Edit task':'Add task',`<form data-cn-task-form="${t.id||''}" id="cn-task-form" style="display:grid;gap:10px;max-height:60vh;overflow-y:auto">${cnField('title','Task heading',t.title,'text','required maxlength="120"')}<label class="field"><span>Description</span><textarea class="input" name="description" maxlength="1000">${escapeHTML(t.description||'')}</textarea></label><label class="field"><span>Task type</span><select class="input" name="kind"><option value="social" ${t.kind==='social'?'selected':''}>Social / promotion (user sends proof, admin reviews)</option><option value="invite" ${t.kind==='invite'?'selected':''}>Invite friends who invest</option><option value="invest" ${t.kind==='invest'?'selected':''}>Participate in earn plans (auto reward, no expiry)</option></select></label>${cnPlanPick(t.plan_ids)}${cnField('link','Task link (hidden behind a button)',t.link,'url')}${cnField('reward_coins','Reward (CN)',t.reward_coins,'number','min="1" required')}${cnField('invite_target','Invites needed (invite tasks only)',t.invite_target,'number','min="0"')}<label><input type="checkbox" name="active" ${t.active?'checked':''}> Visible to users</label></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" form="cn-task-form">Save task</button>`);return;}
 const ce=e.target.closest('[data-cn-camp-edit]');if(ce){const c=cnAdmin.campaigns.find(x=>x.id===ce.dataset.cnCampEdit)||{max_participations:10,prize_type:'cn',prizes:[5000,3000,1000],status:'active'};showModal(c.id?'Edit campaign':'Add campaign',`<form data-cn-camp-form="${c.id||''}" id="cn-camp-form" style="display:grid;gap:10px;max-height:60vh;overflow-y:auto">${cnField('title','Campaign heading',c.title,'text','required maxlength="120"')}<label class="field"><span>Description</span><textarea class="input" name="description" maxlength="1000">${escapeHTML(c.description||'')}</textarea></label><label class="field"><span>Campaign type</span><select class="input" name="kind"><option value="proof" ${c.kind!=='invest'?'selected':''}>Challenge with proof (admin reviews)</option><option value="invest" ${c.kind==='invest'?'selected':''}>Participate in investment plans (auto count)</option></select></label>${cnField('invest_target','Investment plans to reach (invest type)',c.invest_target||10,'number','min="0"')}${cnField('reward_coins','Total CN reward, split per plan (invest type)',c.reward_coins||0,'number','min="0"')}${cnPlanPick(c.plan_ids)}${cnField('link','Challenge post link (hidden behind a button)',c.link,'url')}${cnField('max_participations','Participation count (max entries per person)',c.max_participations,'number','min="1" required')}${cnField('max_total_entries','Campaign capacity (total entries, 0 = no limit)',c.max_total_entries||0,'number','min="0"')}${cnField('ends_at','End date',cnLocalDT(c.ends_at),'datetime-local','required')}<label class="field"><span>Prize type</span><select class="input" name="prize_type"><option value="cn" ${c.prize_type==='cn'?'selected':''}>CN coins</option><option value="cash" ${c.prize_type==='cash'?'selected':''}>Cash balance (USD)</option></select></label>${cnField('prizes','Prize per rank, comma separated (1st, 2nd, 3rd…; optional for invest type)',(c.prizes||[]).join(', '),'text')}<label><input type="checkbox" name="visible" ${c.status!=='hidden'?'checked':''}> Visible to users</label></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit" form="cn-camp-form">Save campaign</button>`);return;}
});
document.addEventListener('submit',async e=>{
 const sb=getSupabase();
 const tp=e.target.closest('[data-cn-task-proof],[data-cn-camp-proof]');if(tp){e.preventDefault();const proof=String(new FormData(tp).get('proof')||'');const {error}=await sb.rpc('cn_submit_proof',{p_task:tp.dataset.cnTaskProof||null,p_campaign:tp.dataset.cnCampProof||null,p_proof:proof});if(error){toast('Not submitted',error.message);return;}await loadCNRewards();render();toast('Proof sent','An admin will review it soon.');return;}
 const tf=e.target.closest('[data-cn-task-form]');if(tf){e.preventDefault();const d=new FormData(tf);const row={title:String(d.get('title')).trim(),description:String(d.get('description')||''),kind:d.get('kind'),link:String(d.get('link')||'').trim(),reward_coins:Number(d.get('reward_coins')),invite_target:Math.max(0,parseInt(d.get('invite_target'),10)||0),plan_ids:d.getAll('plan_ids'),active:d.get('active')==='on'};if(!row.title||!(row.reward_coins>0)||(row.kind==='invite'&&row.invite_target<1)){toast('Check the form','Heading, reward and (for invite tasks) invites needed are required.');return;}const id=tf.dataset.cnTaskForm;const {error}=id?await sb.from('cn_tasks').update(row).eq('id',id):await sb.from('cn_tasks').insert(row);if(error){toast('Save failed',error.message);return;}modalRoot.innerHTML='';await loadAdminCN();await loadCNRewards();render();toast('Task saved',row.title);return;}
 const cf=e.target.closest('[data-cn-camp-form]');if(cf){e.preventDefault();const d=new FormData(cf);const prizes=String(d.get('prizes')||'').split(',').map(x=>Number(x.trim())).filter(x=>x>0);const row={title:String(d.get('title')).trim(),description:String(d.get('description')||''),link:String(d.get('link')||'').trim(),max_participations:Math.max(1,parseInt(d.get('max_participations'),10)||1),max_total_entries:Math.max(0,parseInt(d.get('max_total_entries'),10)||0),ends_at:new Date(String(d.get('ends_at'))).toISOString(),prize_type:d.get('prize_type'),prizes,status:d.get('visible')==='on'?'active':'hidden',kind:d.get('kind')==='invest'?'invest':'proof',invest_target:Math.max(0,parseInt(d.get('invest_target'),10)||0),reward_coins:Math.max(0,Number(d.get('reward_coins'))||0),plan_ids:d.getAll('plan_ids')};if(!row.title||(row.kind==='proof'&&!prizes.length)||(row.kind==='invest'&&(row.invest_target<1||!(row.reward_coins>0)))){toast('Check the form',row.kind==='invest'?'Heading, plans to reach and total CN reward are required.':'Heading and at least one prize are required.');return;}const id=cf.dataset.cnCampForm;const {error}=id?await sb.from('cn_campaigns').update(row).eq('id',id):await sb.from('cn_campaigns').insert(row);if(error){toast('Save failed',error.message);return;}modalRoot.innerHTML='';await loadAdminCN();await loadCNRewards();render();toast('Campaign saved',row.title);return;}
});
document.addEventListener('submit',async e=>{
 const pw=e.target.closest('[data-pw-form]');if(pw){e.preventDefault();const d=new FormData(pw);const p=String(d.get('password')),c=String(d.get('confirm'));if(p.length<8){toast('Too short','Password needs at least 8 characters.');return;}if(p!==c){toast('Mismatch','Passwords do not match.');return;}const {error}=await getSupabase().auth.updateUser({password:p});if(error){toast('Not updated',error.message);return;}modalRoot.innerHTML='';toast('Password updated','Use your new password the next time you log in.');return;}
 const pin=e.target.closest('[data-pin-form]');if(pin){e.preventDefault();const d=new FormData(pin);const p=String(d.get('pin')),c=String(d.get('confirm'));if(!/^[0-9]{4,6}$/.test(p)){toast('Invalid PIN','Use 4 to 6 digits.');return;}if(p!==c){toast('Mismatch','PINs do not match.');return;}const {error}=await getSupabase().rpc('set_withdrawal_pin',{_pin:p});if(error){toast('Not saved',error.message);return;}profileSecurity.pin=true;modalRoot.innerHTML='';render();toast('PIN saved','Your withdrawal PIN is now active.');return;}
 const mf=e.target.closest('[data-mfa-form]');if(mf){e.preventDefault();const code=String(new FormData(mf).get('code'));const sb=getSupabase();const factorId=mf.dataset.mfaForm;const {data:ch,error:ce}=await sb.auth.mfa.challenge({factorId});if(ce){toast('MFA error',ce.message);return;}const {error}=await sb.auth.mfa.verify({factorId,challengeId:ch.id,code});if(error){toast('Wrong code',error.message);return;}profileSecurity.mfa=true;modalRoot.innerHTML='';render();toast('MFA enabled','Your account now asks for an authenticator code at login.');return;}
});

document.addEventListener('change',async e=>{
 const f=e.target.closest('#avatar-file');if(!f||!f.files||!f.files[0])return;const file=f.files[0];f.value='';
 if(!file.type.startsWith('image/')){toast('Not an image','Choose a JPG, PNG or similar image file.');return;}
 if(file.size>5*1024*1024){toast('Too large','Profile photos must be under 5 MB.');return;}
 const sb=getSupabase();const uid=authState.user?.id;if(!uid)return;
 const path=`${uid}/avatar`;
 const {error}=await sb.storage.from('avatars').upload(path,file,{upsert:true,contentType:file.type});
 if(error){toast('Upload failed',error.message);return;}
 await sb.from('profiles').update({avatar_url:path,updated_at:new Date().toISOString()}).eq('user_id',uid);
 const {data:signed}=await sb.storage.from('avatars').createSignedUrl(path,3600);
 profile.avatar=signed?.signedUrl||'';render();toast('Photo updated','Your profile photo is saved.');
});

document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');const a=el?.dataset.action;
if(a==='ai-invite'){const code=referralStats?.code||'';if(!code){toast('Invitation unavailable','Refresh your account and try again.');return;}
showModal('Write an invitation',`<p>Tell us a little about who you're inviting. AI will draft a neutral message with your code <strong>${escapeHTML(code)}</strong>.</p><label class="demo-field">Their name<input id="ai-inv-name" maxlength="60" placeholder="e.g. Sarah"></label><label class="demo-field">How you know them (optional)<input id="ai-inv-rel" maxlength="60" placeholder="e.g. colleague, cousin"></label><label class="demo-field">Their interests (optional)<input id="ai-inv-int" maxlength="200" placeholder="e.g. saving, technology"></label><label class="demo-field">Send via<select id="ai-inv-ch" class="input"><option value="whatsapp">WhatsApp</option><option value="sms">SMS</option><option value="email">Email</option><option value="social">Social media</option></select></label><div id="ai-inv-out"></div>`,`<button class="btn" data-action="close-modal">Close</button><button class="btn primary" data-action="ai-invite-go">Draft message</button>`);}
if(a==='ai-invite-go'){const name=document.getElementById('ai-inv-name')?.value.trim();if(!name){toast('Name needed','Enter the name of the person you are inviting.');return;}
const out=document.getElementById('ai-inv-out');el.disabled=true;el.textContent='Drafting…';
try{const r=await apiCall('/api/public/invite-message',{method:'POST',body:JSON.stringify({name,relationship:document.getElementById('ai-inv-rel').value.trim(),interests:document.getElementById('ai-inv-int').value.trim(),channel:document.getElementById('ai-inv-ch').value,code:referralStats?.code||''})});
out.innerHTML=`<label class="demo-field">Your message (you can edit it)<textarea id="ai-inv-msg" class="input" rows="6" style="width:100%;resize:vertical">${escapeHTML(r.message||'')}</textarea></label><button class="btn small" data-action="ai-invite-copy">Copy message</button>`;el.textContent='Draft again';}
catch(err){out.innerHTML=`<div class="helper" role="alert">${escapeHTML(err?.message||'Could not draft the message.')}</div>`;el.textContent='Draft message';}
finally{el.disabled=false;}}
if(a==='ai-invite-copy'){navigator.clipboard?.writeText(document.getElementById('ai-inv-msg')?.value||'');toast('Message copied','Paste it wherever you want to send it.');}
});

// WhatsApp share promo: 10 shares unlock 2000 CN (counted server-side, one-time)
let cnShare=null,cnSharePopupShown=false,ugxRate=null;
async function loadShareStatus(){const sb=getSupabase();if(!sb||!authState.user)return;const [{data},fx]=await Promise.all([sb.rpc('cn_share_status'),ugxRate?Promise.resolve(null):sb.from('fx_rates').select('units_per_usd').eq('currency','UGX').maybeSingle()]);cnShare=data||null;if(fx?.data)ugxRate=Number(fx.data.units_per_usd);}
function shareModalBody(){const s=cnShare||{shares:0,target:10,reward:2000};const usd=s.reward*(cnRewards?.price_usd||0.48);const ugx=ugxRate?new Intl.NumberFormat('en-UG').format(Math.round(usd*ugxRate)):'—';const n=Math.min(s.shares,s.target);const pct=Math.round(n/s.target*100);
return `<div class="share-promo"><img src="${CN_COIN_URL}" alt="CN coin" class="share-promo-coin" onerror="this.style.display='none'"><h3>Unlock ${s.reward.toLocaleString()} CN</h3><p class="share-promo-value">Worth <strong>$${usd.toFixed(2)}</strong> · <strong>UGX ${ugx}</strong></p><p>Share CRYPTONVA with <strong>${s.target} WhatsApp friends or groups</strong> and the coins are added to your CN balance automatically.</p><div class="share-promo-bar"><span style="width:${pct}%"></span></div><p class="helper">${s.claimed?'✓ Reward received — thank you for sharing!':`${n}/${s.target} shares · ${s.target-n} to go`}</p></div>`;}
function showSharePromo(){showModal('Share & earn CN',shareModalBody(),cnShare?.claimed?`<button class="btn" data-action="close-modal">Close</button>`:`<button class="btn" data-action="close-modal">Later</button><button class="btn whatsapp-btn" data-action="wa-share">Share on WhatsApp</button>`);}
const _loadCNOrig=loadCNRewards;
loadCNRewards=async function(){await _loadCNOrig();try{await loadShareStatus();}catch(e){}};
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');const a=el?.dataset.action;
if(a==='share-promo'){if(!cnShare)await loadShareStatus();showSharePromo();}
if(a==='wa-share'){const code=referralStats?.code||'';const text=`I'm using CRYPTONVA, a digital investment platform. Sign up and enter my invitation code ${code} in the "Invitation code" field to get 800 CN welcome coins. ${location.origin}`;window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank');
const {data,error}=await getSupabase().rpc('cn_record_share');if(error){toast('Share not counted','Please try again.');return;}const was=cnShare?.claimed;cnShare=data;if(cnShare.claimed&&!was){toast('+2,000 CN unlocked!','The reward has been added to your CN balance.');await _loadCNOrig();render();}showSharePromo();}
});
